        '98UBCKKHD-F3FF' => ['short' => 'A finely finished round collar shirt cut for bishops — episcopal clergy wear tailored to order in Nairobi.', 'description' => '<p>Cut with bishops in mind, this <strong>Round Collar Shirt</strong> brings finely finished tailoring to the episcopal wardrobe. The full round collar shows white all the way round — the timeless mark of ordained ministry, worn here with a bishop\'s bearing.</p><p>Each shirt is made to order in our Nairobi workshop at Sonalux House, Moi Avenue, and our tailors will advise on the colours traditionally associated with your office and tradition. Wear it under a cassock or cope for liturgies, or on its own for daily episcopal ministry.</p><p>Serving bishops, archbishops and senior clergy across Kenya and East Africa — Anglican/ACK, Catholic, Methodist, Pentecostal and independent — with delivery worldwide.</p>', 'features' => [['icon' => '⛪', 'text' => 'Cut for bishops, archbishops and senior clergy'], ['icon' => '⚪', 'text' => 'Full round collar — white showing all the way round'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop, cut to your fit'], ['icon' => '🎨', 'text' => 'Tailors advise on colours traditionally associated with your office'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['bishop shirt kenya', 'bishops clergy shirt', 'round collar shirt for bishops', 'askofu shirt', 'episcopal shirt nairobi', 'clergy shirts kenya', 'dog collar shirt', 'bishop attire nairobi'], 'seo' => ['meta_title' => 'Bishop\'s Round Collar Shirt — Nairobi, Kenya', 'meta_description' => 'Round collar clergy shirts finely tailored for bishops in Nairobi — made to order. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'bishop shirt kenya, bishops round collar shirt, episcopal clergy shirt nairobi, bishop attire kenya, clergy shirts nairobi, round collar shirt kenya, bishop regalia kenya', 'og_title' => 'Round Collar Shirt for Bisho