        'CAC-001-01' => ['short' => 'Detachable white clergy collar — the crisp finishing touch for collar-ready shirts, bibs and cassocks.', 'description' => '<p>Small as it is, the white collar is the most recognised sign of ministry in the world. The <strong>Straight Collar</strong> is Bethany House\'s detachable clergy collar — the crisp white band that slots into collar-ready shirts, bibs (clergy rabats) and cassock necklines to complete the clerical look.</p><p>Because it detaches, it is easy to keep spotless and simple to replace, letting your shirts serve longer while the collar stays bright. Keep a spare in the vestry drawer or the clergy bag — a small purchase that is never wasted, and our team will help you match the right size to your neckline.</p><p>An everyday essential for pastors, reverends, priests and bishops across Kenya and East Africa. Order alongside our clergy shirts, bibs and cassock sets, with delivery worldwide from our Nairobi shop at Sonalux House, Moi Avenue.</p>', 'features' => [['icon' => '⚪', 'text' => 'Crisp detachable white clergy collar'], ['icon' => '🔄', 'text' => 'Slots into collar-ready shirts, bibs and cassock necklines'], ['icon' => '🧼', 'text' => 'Detaches for easy cleaning and simple replacement'], ['icon' => '🙏', 'text' => 'Everyday essential for pastors, reverends, priests and bishops'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['clergy collar kenya', 'detachable clergy collar', 'white collar clergy', 'priest collar nairobi', 'dog collar insert', 'reverend collar', 'clerical collar kenya', 'collar for clergy shirt'], 'seo' => ['meta_title' => 'Clergy Collar — Detachable Straight Collar, Kenya', 'meta_description' => 'Detachable white clergy collars in Nairobi — the crisp finish for collar-ready shirts, bibs and cassocks. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'clergy collar kenya, detachable clergy collar, clergy collar price kenya, white clerical collar nairobi, priest collar kenya, reverend collar, clergy accessories nairobi', 'og_title' => 'Straight Collar — The Crisp White Mark of Ministry', 'og_description' => 'Bethany House\'s detachable white clergy collar: slots into collar-ready shirts, bibs and cassocks, and detaches for easy care. Delivered across Kenya, East Africa and worldwide.']],
        'CHA-BCC-001' => ['short' => 'A brass chalice for Holy Communion — warm traditional lustre in the classic cup, stem and foot form, made to serve for generations.', 'description' => '<p>The chalice is the most honoured vessel on the altar — the cup that holds the wine of Holy Communion, recalling the cup our Lord shared at the Last Supper. This brass chalice follows the classic form handed down through the centuries — cup, stem and foot — made to stand on the altar and sit comfortably in the celebrant\'s hand.</p><p>Brass has long been the church\'s practical choice for altar ware — warm in colour, substantial in the hand and made to serve faithfully for generations. It is equally at home at a Catholic Mass, an Anglican (ACK) Holy Communion or a Methodist, PCEA or independent-church Lord\'s Supper.</p><ul><li><strong>Brass</strong> with a warm, traditional lustre</li><li>Classic cup, stem and foot form for confident handling during the liturgy</li><li>Made to stand on the altar or communion table</li><li>Care: hand-wash in warm water with mild soap; dry at once with a soft, lint-free cloth</li></ul><p>Chosen with reverence, delivered with care — from Sonalux House, Moi Avenue, Nairobi, to churches across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🏆', 'text' => 'Brass construction — warm in colour and substantial in the hand'], ['icon' => '✋', 'text' => 'Classic cup, stem and foot form — comfortable in the celebrant\'s hand when the cup is raised'], ['icon' => '⚖️', 'text' => 'Made to stand on the altar or communion table'], ['icon' => '⛪', 'text' => 'At home in Catholic, Anglican (ACK), Methodist, PCEA and independent-church worship'], ['icon' => '🧼', 'text' => 'Simple care: hand-wash in warm water and dry at once with a soft, lint-free cloth'], ['icon' => '🚚', 'text' => 'From Sonalux House, Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide']], 'aliases' => ['brass communion cup', 'communion chalice', 'chalice kenya', 'church chalice nairobi', 'kikombe cha ushirika', 'mass chalice', 'goblet chalice'], 'seo' => ['meta_title' => 'Brass Chalice Cup in Nairobi, Kenya', 'meta_description' => 'A brass chalice for Holy Communion. From Sonalux House, Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide. Order for your church.', 'meta_keywords' => 'brass chalice, chalice kenya, communion chalice nairobi, church chalice, chalice cup price in kenya, holy communion ware kenya, communion ware nairobi, mass chalice', 'og_title' => 'Brass Chalice Cup — Chosen with Reverence, Delivered with Care', 'og_description' => 'The classic brass chalice for Holy Communion — warm traditional lustre in the timeless cup, stem and foot form. From Bethany House, Nairobi, to altars across Kenya and beyond.']],
        'CHI-FC-001' => ['short' => '102 beloved Bible stories retold in simple words, with full-colour illustrations on every page and a Scripture reference for each story.', 'description' => '<p><strong>102 Favorite Children\'s Bible Stories</strong> walks young readers through the best-loved accounts of the Old and New Testaments in simple, easy-to-understand language — one engaging story at a time, helping children learn about God, Jesus Christ and the teachings of the Bible from an early age.</p><ul><li>Full-colour illustrations on every page hold a child\'s attention</li><li>A Scripture reference with each story, so families can open the Bible together</li><li>Durable, child-friendly design made for small hands</li><li>Simple words suited to early readers</li></ul><p>A favourite for bedtime reading and family devotions, and a popular choice for <strong>Sunday-school prize-givings</strong> and end-of-term awards — order in quantity for your children\'s ministry.</p><p>Chosen with reverence, delivered with care — from Sonalux House, Moi Avenue, Nairobi, to churches across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📖', 'text' => '102 best-loved Bible stories retold in simple, easy-to-understand words'], ['icon' => '🎨', 'text' => 'Full-colour illustrations on every page hold a child\'s attention'], ['icon' => '✝️', 'text' => 'Scripture reference with each story points children back to God\'s Word'], ['icon' => '🧒', 'text' => 'Durable, child-friendly design made for small hands'], ['icon' => '🎁', 'text' => 'Ideal Sunday-school prize, bedtime storybook and family-devotions companion']], 'aliases' => ['children bible stories book', 'bible storybook for kids', 'sunday school prize book kenya', 'kids bible stories nairobi', 'favourite bible stories', '102 favorite bible stories', 'children\'s story bible', 'bible stories for children'], 'seo' => ['meta_title' => '102 Favorite Bible Stories for Children in Kenya', 'meta_description' => 'Illustrated Bible storybook — 102 beloved stories in simple words with Scripture references. Delivered across Kenya and worldwide. Shop today.', 'meta_keywords' => 'children bible stories, bible storybook kenya, kids bible nairobi, sunday school prizes, illustrated bible stories, children bible kenya, bedtime bible stories, family devotions book', 'og_title' => '102 Favorite Children\'s Bible Stories', 'og_description' => 'One beloved story, one bright illustration at a time — introduce your child to God\'s Word. Chosen with reverence, delivered with care across Kenya and worldwide.']],
        'CLE-A-001' => ['short' => 'A simple white full-length, long-sleeved alb — the garment of baptismal purity for servers, lectors, deacons and priests.', 'description' => '<p>The alb is the church\'s quiet foundation garment — a simple, full-length, long-sleeved robe, usually white, worn beneath stole and chasuble as a symbol of baptismal purity. It is often the first vestment a server ever puts on, and the one a priest wears beneath everything else.</p><p>Each alb is tailored in-house at our Nairobi workshop and can be made in different designs according to your specifications — from plain simplicity to more detailed finishes.</p><p><strong>Worn by</strong> altar servers, lectors, deacons and priests, it serves the whole sanctuary team across:</p><ul><li>Baptisms</li><li>Communion services</li><li>Confirmations</li><li>Adoration</li><li>Weddings</li></ul>', 'features' => [['icon' => '🕊️', 'text' => 'White, full-length and long-sleeved — the symbol of baptismal purity'], ['icon' => '👥', 'text' => 'Worn by altar servers, lectors, deacons and priests alike'], ['icon' => '✂️', 'text' => 'Different designs available, made to your specifications in Nairobi'], ['icon' => '⛪', 'text' => 'For baptisms, communion services, confirmations, adoration and weddings'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['white alb', 'priest alb', 'altar server robe', 'alb kenya', 'white church robe', 'alb vestment', 'deacon alb'], 'seo' => ['meta_title' => 'Albs in Nairobi, Kenya — Tailored to Order', 'meta_description' => 'White full-length albs for priests, deacons, lectors and altar servers — tailored in Nairobi to your specifications. Delivered across Kenya and East Africa.', 'meta_keywords' => 'alb kenya, white alb nairobi, priest alb, altar server robes kenya, church robes nairobi, clergy vestments kenya, alb price in kenya, deacon alb', 'og_title' => 'The Alb — Baptismal Purity, Tailored in Nairobi', 'og_description' => 'The church\'s foundational white vestment — worn by servers, lectors, deacons and priests at baptisms, communion, confirmations and weddings. Made to your specifications.']],
        'CLE-AB-001' => ['short' => 'Altar bells in single, double, triple and four-bell styles — a clear, bright ring for the holiest moments of the Mass.', 'description' => '<p>The altar bell — also called a sanctuary bell or Sanctus bell — is rung at the most sacred moments of the Eucharist, most memorably at the consecration and each elevation of the host and chalice. A practice dating from about the thirteenth century, its bright voice announces joy: heaven touching earth at the Lord\'s table.</p><p><strong>Features:</strong></p><ul><li>Polished brass or gold-plated brass — durable and easy to maintain</li><li>Available in single, double, triple and four-bell cluster styles</li><li>Comfortable handle for a clean, easy ring</li><li>Clear, bright tone suited to church worship</li></ul><p>Serving altar servers and sacristans in Catholic, Anglican and Orthodox parishes across Kenya and East Africa — for Holy Mass, Eucharistic consecration and Benediction. Chosen with reverence, delivered with care from Nairobi, worldwide.</p>', 'features' => [['icon' => '🔔', 'text' => 'Rung at the consecration and each elevation — the joyful sound of heaven touching earth'], ['icon' => '✨', 'text' => 'Polished brass or gold-plated brass, durable and easy to maintain'], ['icon' => '🎶', 'text' => 'Clear, bright tone that carries through the sanctuary'], ['icon' => '🤲', 'text' => 'Comfortable grip handle for altar servers of every age'], ['icon' => '🛎️', 'text' => 'Single, double, triple and four-bell cluster styles available'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide from Nairobi CBD']], 'aliases' => ['altar bell', 'sanctuary bell', 'mass bell', 'sanctus bell', 'church bells set', 'kengele', 'communion bell', 'four bell cluster', 'altar bells kenya'], 'seo' => ['meta_title' => 'Altar & Sanctuary Bells in Nairobi, Kenya', 'meta_description' => 'Brass altar bells in single to four-bell styles, rung at the consecration. Order for your church from Nairobi — delivery across Kenya and worldwide.', 'meta_keywords' => 'altar bell kenya, sanctuary bell nairobi, sanctus bell, mass bell church, four bell cluster, kengele ya kanisa, altar server bells, benediction bell, church supplies nairobi cbd', 'og_title' => 'Altar Bells — A Joyful Sound at the Consecration', 'og_description' => 'Polished brass sanctuary bells in single, double, triple and four-bell styles. Chosen with reverence in Nairobi, delivered with care worldwide.']],
        'CLE-B-001' => ['short' => 'Clergy bib (rabat) with a collar insert slot — the smart shirtfront that completes the clerical look over any shirt.', 'description' => '<p>The <strong>Bib</strong> — known more formally as a clergy rabat or shirtfront — is one of ministry\'s most practical garments: not a shirt, but a smart front with a place to insert a clergy collar, worn over a shirt to give the full clerical appearance in moments.</p><p>Slip it over a crisp white shirt, insert the collar, and you are ready for the pulpit, a pastoral visit or a committee meeting — with less laundering and lighter wear than a full clergy shirt, which makes it a favourite with busy ministers.</p><p>Pair it with our White Shirt – Normal and a detachable Straight Collar for the classic look. Serving pastors, reverends, priests and bishops across Kenya and East Africa, with delivery worldwide from Sonalux House, Moi Avenue, Nairobi.</p>', 'features' => [['icon' => '👔', 'text' => 'Smart clergy shirtfront (rabat) — not a shirt, worn over one'], ['icon' => '⚪', 'text' => 'Fitted with a slot to insert a clergy collar'], ['icon' => '🔄', 'text' => 'Turns any smart shirt into full clerical dress in moments'], ['icon' => '🤝', 'text' => 'Pairs with our white shirts and detachable collars'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['clergy bib kenya', 'rabat', 'clergy rabat', 'shirtfront clergy', 'clergy vest', 'collar bib nairobi', 'clerical vest kenya', 'bib for clergy collar'], 'seo' => ['meta_title' => 'Clergy Bib (Rabat) in Nairobi, Kenya', 'meta_description' => 'Clergy bibs (rabats) with a collar insert slot — the smart shirtfront worn over a shirt. Shop in Nairobi with delivery across Kenya and East Africa.', 'meta_keywords' => 'clergy bib kenya, clergy rabat nairobi, clergy shirtfront, collar bib kenya, clerical vest, clergy accessories nairobi, clergy wear kenya', 'og_title' => 'Bib — The Clergy Rabat That Completes the Look', 'og_description' => 'Worn over a shirt with a collar inserted, the bib gives the full clerical appearance in moments. A practical favourite for ministers — delivered across Kenya, East Africa and worldwide.']],
        'CLE-B-009' => ['short' => 'Clergy garment bag that carries and protects cassocks, gowns and vestments — in the vestry, and on the road between congregations.', 'description' => '<p>Sacred vestments deserve to arrive the way they left the tailor\'s hands. This clergy garment bag carries and protects cassocks, chasubles, preaching gowns and stoles from dust and creasing — in the vestry between services, and on the road between congregations.</p><p>It is the quiet workhorse of every well-kept sacristy: garments go in cared-for and come out ready for the altar.</p><p>A thoughtful companion for travelling bishops, visiting preachers and ministers serving several congregations — and a natural partner to our made-to-measure vestments, tailored in-house in Nairobi. Available at Sonalux House, Moi Avenue, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🧥', 'text' => 'Carries and protects cassocks, chasubles, preaching gowns and stoles'], ['icon' => '🛡️', 'text' => 'Shields sacred garments from dust and wear in vestry storage'], ['icon' => '🧳', 'text' => 'Made for the travelling minister — conferences, ordinations and Sunday circuits'], ['icon' => '✨', 'text' => 'Garments go in cared-for and come out ready for the altar'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['garment bag', 'vestment bag', 'cassock bag', 'clergy garment bag', 'robe bag', 'gown carrier', 'suit bag for clergy', 'vestment cover'], 'seo' => ['meta_title' => 'Clergy Garment Bags in Nairobi, Kenya', 'meta_description' => 'Garment bag for cassocks, gowns and vestments — protected and travel-ready. From Sonalux House, Nairobi; delivery Kenya-wide and worldwide.', 'meta_keywords' => 'clergy garment bag kenya, vestment bag nairobi, cassock bag, preaching gown bag, clergy travel bag, robe carrier kenya, church supplies nairobi cbd', 'og_title' => 'The Clergy Garment Bag — Ready for the Altar', 'og_description' => 'Protection for cassocks, chasubles and preaching gowns — in the vestry and on the road. Delivered with care from Nairobi.']],
        'CLE-C-123' => ['short' => 'Quality pectoral cross for pastors, reverends and bishops — available in gold-tone and silver-tone finishes.', 'description' => '<p>The pectoral cross is worn at the centre of the chest — from the Latin <strong>pectus</strong> — and since the late Middle Ages it has marked the office of bishops and senior clergy. Today it is carried with equal honour by pastors, reverends, apostles and overseers across Kenya’s churches.</p><p>Bethany House offers this quality, high-end pectoral cross in the two classic conventions: a warm <strong>gold-tone</strong> finish and a bright <strong>silver-tone</strong> finish, so you can match your vestments and the occasion.</p><ul><li>Available in gold-tone and silver-tone finishes</li><li>Suited to pastors, reverends, bishops and senior clergy</li><li>Worn at the chest as a visible confession of the cross of Christ</li><li>A treasured gift for ordinations, consecrations and ministry anniversaries</li></ul><p>Chosen with reverence at Sonalux House, Moi Avenue, Nairobi — delivered with care across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✝️', 'text' => 'Two classic finishes: gold-tone and silver-tone'], ['icon' => '👔', 'text' => 'For pastors, reverends, bishops and senior clergy'], ['icon' => '🎁', 'text' => 'A treasured gift for ordinations and consecrations'], ['icon' => '📿', 'text' => 'Worn at the centre of the chest in the church’s historic tradition'], ['icon' => '🏛️', 'text' => 'Chosen with reverence at Sonalux House, Moi Avenue, Nairobi'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['bishop cross', 'clergy cross', 'msalaba', 'chest cross', 'priest cross', 'pastor cross', 'pectoral cross kenya', 'cross for bishops', 'silver pectoral cross', 'gold pectoral cross'], 'seo' => ['meta_title' => 'Pectoral Cross in Nairobi, Kenya — Gold & Silver Tone', 'meta_description' => 'Quality pectoral crosses for pastors, reverends and bishops in gold-tone or silver-tone. From Nairobi CBD, delivered across Kenya and worldwide. Shop today.', 'meta_keywords' => 'pectoral cross kenya, pectoral cross nairobi, bishop cross kenya, clergy cross nairobi, gold pectoral cross, silver pectoral cross, msalaba, bishop regalia kenya, church supplies nairobi cbd, clergy accessories kenya', 'og_title' => 'The Pectoral Cross — Worn Over the Heart, in Gold or Silver Tone', 'og_description' => 'Since the late Middle Ages the mark of bishops and senior clergy. Choose gold-tone or silver-tone at Bethany House, Nairobi — delivered across Kenya and worldwide.']],
        'CLE-CS-001' => ['short' => 'Complete cassock outfit in one order — cassock, stole, belt, straight collar shirt and a 12 inch clergy collar.', 'description' => '<p>The Cassock Set robes a minister completely in a single order. At its heart is the cassock — the ankle-length garment that has marked the clergy for centuries — accompanied by everything traditionally worn with it.</p><p>The set consists of:</p><ul><li>A cassock</li><li>A stole — the badge of ordained ministry</li><li>A belt (cincture)</li><li>A straight collar shirt</li><li>A 12 inch clergy collar</li></ul><p>From the first robing at ordination to faithful weekly service, this set serves pastors, priests and ministers across Kenya\'s church family — Anglican, Catholic, Methodist, PCEA, Pentecostal and independent congregations alike — with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📦', 'text' => 'Five pieces: cassock, stole, belt, straight collar shirt and 12 inch collar'], ['icon' => '🕊️', 'text' => 'Ordination-ready — robed from collar to hem in a single order'], ['icon' => '🎗️', 'text' => 'Includes the stole, the badge of ordained ministry'], ['icon' => '⛪', 'text' => 'Serves pastors, priests and ministers across all denominations'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['full cassock set', 'cassock and stole set', 'complete clergy outfit', 'ordination cassock set', 'clergy set', 'priest cassock set', 'cassok set', 'clergy robes set kenya'], 'seo' => ['meta_title' => 'Cassock Set — Complete Clergy Outfit in Kenya', 'meta_description' => 'Complete cassock set — cassock, stole, belt, straight collar shirt and 12 inch collar. Order online with delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'cassock set kenya, complete clergy outfit, cassock and stole set, straight collar shirt, clergy collar kenya, ordination cassock set, clergy attire nairobi, church robes kenya', 'og_title' => 'Cassock Set — Robed from Collar to Hem in One Order', 'og_description' => 'Cassock, stole, belt, straight collar shirt and 12 inch collar — everything a minister wears, gathered into one set. Chosen with reverence, delivered with care across Kenya and beyond.']],
        'CLE-DSS-001' => ['short' => 'Two-colour stole worn either way round — flip from one liturgical season to the next without buying a second stole.', 'description' => '<p>This double-sided stole carries one colour on one side and a second on the other — two liturgical colours in a single, thoughtfully made vestment. When the church calendar turns, simply turn the stole with it.</p><p>It is practical wisdom for ordained ministry: colours belonging to different seasons of the church year are joined in one stole, maximising its use through interchanging seasons — penitential purple giving way to festal white, or the green of Ordinary Time to Pentecost red, according to the pairing you choose.</p><p>Tailored in-house at our Nairobi workshop, it serves priests, pastors and deacons across Kenya and East Africa who want a vestment wardrobe that works as faithfully as they do.</p>', 'features' => [['icon' => '🔄', 'text' => 'Two liturgical colours in one stole — turn it as the seasons change'], ['icon' => '💡', 'text' => 'Maximises use: one vestment serves two seasons of the church year'], ['icon' => '🎨', 'text' => 'Pair penitential and festal colours to suit your tradition\'s calendar'], ['icon' => '✂️', 'text' => 'Tailored in-house at our Nairobi workshop'], ['icon' => '⛪', 'text' => 'A practical staple for priests, pastors and deacons']], 'aliases' => ['reversible stole kenya', 'two in one stole', 'stole two colours', 'double faced stole', 'clergy stole nairobi', 'pastor stole kenya', 'seasonal church stole'], 'seo' => ['meta_title' => 'Reversible Two-Colour Clergy Stole — Kenya', 'meta_description' => 'A stole with one colour each side — turn it as the church seasons change. Tailored in Nairobi, delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'double sided stole, reversible clergy stole kenya, two colour stole nairobi, stole for church seasons, priest stole nairobi, clergy vestments kenya, ordination stole', 'og_title' => 'Double-Sided Stole — Turn It with the Seasons', 'og_description' => 'One colour on one side, another on the reverse: a single stole that serves two seasons of the church year. Tailored with reverence in Nairobi.']],
        'CLE-ECW-001' => ['short' => 'Efrat communion wine from Israel — wine from the land of the Bible for the Lord\'s Table, delivered across Kenya and beyond.', 'description' => '<p>Efrat communion wine comes <strong>from Israel</strong> — wine for the Lord\'s Table, carried from the land of the Bible itself.</p><p>To fill the cup at Holy Communion from this bottle is to pour from the land where the events of Scripture unfolded — a meaningful link between your congregation\'s worship and the places of the biblical story.</p><p>Well suited to Anglican, Methodist, Pentecostal and independent churches, and a meaningful choice for the great days — confirmations, weddings, ordinations — where the story in the cup matters. Received as your tradition directs.</p><p>From Bethany House, Sonalux House, Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍷', 'text' => 'Efrat communion wine from Israel for the Lord\'s Table'], ['icon' => '📖', 'text' => 'From the land of the Bible — a meaningful link to the places of Scripture'], ['icon' => '⛪', 'text' => 'A storied choice for communion, confirmations, weddings and ordinations'], ['icon' => '✝️', 'text' => 'At home in Anglican, Methodist, Pentecostal and independent churches'], ['icon' => '🌍', 'text' => 'From Israel to your table in Kenya — delivered with care from Nairobi CBD']], 'aliases' => ['communion wine from israel', 'israel altar wine', 'efrat wine', 'holy land communion wine', 'sacramental wine', 'divai', 'communion wine kenya'], 'seo' => ['meta_title' => 'Efrat Communion Wine from Israel — Kenya', 'meta_description' => 'Efrat communion wine from Israel — wine from the land of the Bible for Holy Communion. From Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'efrat communion wine, communion wine from israel, holy land wine kenya, altar wine nairobi, sacramental wine kenya, communion wine for churches kenya, israel church wine, church supplies nairobi', 'og_title' => 'Efrat Communion Wine — From the Land of the Bible', 'og_description' => 'Communion wine from Israel by Efrat — from the land of the Bible to the Lord\'s Table in Kenya. From Bethany House, Nairobi, chosen with reverence.']],
        'CLE-IB-001' => ['short' => 'Chain-swung thurible (censer) for incensing altar and congregation — the rising smoke of prayer in Psalm 141:2.', 'description' => '<p>The thurible — also called a censer or incense burner — is the chain-swung metal vessel from which fragrant incense rises during worship. Grains of incense are spooned onto lit charcoal, and the climbing smoke becomes the Bible\'s own picture of prayer: <strong>"Let my prayer be set before you like incense"</strong> (Psalm 141:2), echoed by the golden censer bearing the prayers of the saints in Revelation 8.</p><p>Carried by the thurifer, the thurible honours the altar, the Gospel book, the Eucharist, the clergy and the congregation — a practice cherished across Catholic, Orthodox, Anglican and Methodist worship, and increasingly loved in independent churches across Kenya and East Africa.</p><p>Chosen with reverence at Sonalux House, Moi Avenue, Nairobi, and delivered across Kenya, East Africa and worldwide. Pair it with our frankincense (ubani) for a complete incensation set.</p>', 'features' => [['icon' => '🔗', 'text' => 'Classic chain-swung censer design for the reverent sweep of incensation at the altar'], ['icon' => '🙏', 'text' => 'The rising smoke of Psalm 141:2 — prayer made visible before the congregation'], ['icon' => '⛪', 'text' => 'At home in Catholic, Orthodox, Anglican, Methodist and independent church worship'], ['icon' => '🔥', 'text' => 'Burns incense grains over lit charcoal — pairs beautifully with our ubani (frankincense)'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['censer', 'incense burner', 'thurible kenya', 'thurble', 'chetezo', 'church incense burner', 'censer for church', 'incense burner nairobi', 'ubani burner'], 'seo' => ['meta_title' => 'Thurible & Incense Burner in Nairobi, Kenya', 'meta_description' => 'Chain-swung thurible (censer) for church worship — chosen with reverence at Sonalux House, Moi Avenue, delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'thurible kenya, censer nairobi, incense burner church, where to buy thurible in nairobi, chetezo, church incense burner kenya, thurifer censer, ubani incense, church supplies nairobi cbd', 'og_title' => 'The Thurible — Prayer Rising Like Incense', 'og_description' => 'A chain-swung censer for altar, Gospel and congregation. Chosen with reverence in Nairobi, delivered with care across Kenya and worldwide.']],
        'CLE-LPD-001' => ['short' => 'Princess-line ladies\' clergy dress with collar insert — a fitted, elegant cut in colours for every rank and season.', 'description' => '<p>The Ladies Princes Dress — a princess-cut clergy dress for lady ministers — gives women in ministry a garment that is both reverent and beautifully fitted. A <strong>collar insert</strong> completes the clerical look at the neckline, ready for the pulpit, the altar and every pastoral duty.</p><p>Because it can be <strong>tailored to fit your own specifications</strong> in our Nairobi workshop, the fit is truly yours. It comes in a <strong>variety of colours representing the different ranks and seasons</strong> of the church, so you can dress for your office and for the church year alike.</p><p>A cherished choice for women clergy, deaconesses, evangelists and lady ministers — for ordinations, Sunday services and every occasion between, with delivery across Kenya and beyond.</p>', 'features' => [['icon' => '👗', 'text' => 'Princess-cut silhouette — a graceful, fitted line made for women in ministry'], ['icon' => '⛪', 'text' => 'Collar insert included for a complete clerical neckline'], ['icon' => '🎨', 'text' => 'Variety of colours representing the different ranks and seasons of the church'], ['icon' => '✂️', 'text' => 'Tailored to fit your own specifications in our Nairobi workshop'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and beyond']], 'aliases' => ['ladies princes dress', 'princess dress', 'ladies clergy dress', 'women clergy dress', 'female pastor dress', 'deaconess dress', 'ladies clergy wear', 'clergy dress kenya'], 'seo' => ['meta_title' => 'Ladies Princess Clergy Dress — Nairobi, Kenya', 'meta_description' => 'Ladies\' clergy dress with collar insert, tailored to your specifications in Nairobi. Colours for every rank and season. Delivered across Kenya and beyond.', 'meta_keywords' => 'ladies princes dress, ladies clergy dress, women clergy attire nairobi, clergy dress for ladies, female clergy wear kenya, deaconess dress, clergy wear nairobi, ladies church dresses', 'og_title' => 'Ladies Princes Dress — Tailored for Women in Ministry', 'og_description' => 'A princess-cut clergy dress with collar insert, in colours for every rank and season. Tailored to your specifications in Nairobi — chosen with reverence, delivered with care.']],
        'CLE-PC-001' => ['short' => 'Pure white ladies\' cassock tailored to order in our Nairobi workshop — a cool, classic garment for everyday ministry.', 'description' => '<p>A pure white princess cassock for the lady minister — the ladies\' cut of the classic clergy cassock, shaped on princess seams so it falls in one graceful, unbroken line from shoulder to hem. Where our White Princes Cassock listing celebrates the festal seasons, this is the everyday classic — the working garment of weekly ministry.</p><p>Across Africa, white has long been favoured for church dress in warm climates: cool, dignified and festal at once. This cassock is <strong>made to order in our Nairobi workshop</strong>, so it fits your frame and your calling.</p><p>It serves women clergy, evangelists, deaconesses and women\'s guild leaders — worn on its own, with a stole for services, or as the foundation of a full vestment wardrobe. Delivered across Kenya, East Africa and beyond.</p>', 'features' => [['icon' => '✨', 'text' => 'Pure white — cool, dignified everyday dress for women in church leadership'], ['icon' => '📏', 'text' => 'Princess-seam cut falls in one graceful, unbroken line from shoulder to hem'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop'], ['icon' => '🎗️', 'text' => 'Pairs beautifully with a stole as the foundation of a full vestment wardrobe'], ['icon' => '🌍', 'text' => 'Delivered across Kenya, East Africa and beyond']], 'aliases' => ['white ladies cassock', 'princess cassock white', 'white cassock for women', 'deaconess cassock', 'ladies white robe', 'white cassok', 'women clergy cassock', 'ladies cassock white kenya'], 'seo' => ['meta_title' => 'White Ladies Cassock — Tailored to Order, Nairobi', 'meta_description' => 'Pure white ladies cassock made to order in Nairobi. Cool, dignified clergy wear for lady ministers, delivered across Kenya and East Africa.', 'meta_keywords' => 'white ladies cassock, princess cassock white, made to order cassock kenya, women clergy robes nairobi, deaconess cassock, ladies clergy wear kenya, white church robe, cassock nairobi', 'og_title' => 'Princes Cassock in White — Tailored for Lady Ministers', 'og_description' => 'The ladies\' cut of the classic cassock in pure white — cool, dignified and made to order in our Nairobi workshop. Chosen with reverence, delivered with care.']],
        'CLE-PCB-001' => ['short' => 'White ladies\' princess cassock for festal seasons — Christmas, Easter, weddings and celebration Sundays, made to order in Nairobi.', 'description' => '<p>White is the church\'s colour of joy — of Christmas and Easter, weddings, baptisms and the feasts of resurrection hope. The White Princes Cassock brings that festal brightness to the ladies\' cassock, cut on elegant <strong>princess seams</strong> for a fitted, flowing line.</p><p><strong>Made to order in our Nairobi workshop</strong>, it is made for the seasons when the church wears white — and, in our warm East African climate, it serves beautifully as year-round dress for women in church leadership.</p><p>Chosen by women clergy, deaconesses and ministry leaders for Easter and Christmas services, weddings, confirmations and celebration Sundays — with delivery across Kenya, East Africa and beyond.</p>', 'features' => [['icon' => '🤍', 'text' => 'White — the liturgical colour of Christmas, Easter, weddings and the church\'s great feasts'], ['icon' => '👗', 'text' => 'Elegant princess-seam cut, fitted and flowing for women in ministry'], ['icon' => '☀️', 'text' => 'Bright, cool festal dress well suited to the East African climate'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and beyond']], 'aliases' => ['white princess cassock', 'ladies white cassock', 'white cassock dress', 'festal cassock', 'white princess dress', 'women white clergy dress', 'white casock', 'easter clergy dress'], 'seo' => ['meta_title' => 'White Princess Cassock for Ladies — Kenya', 'meta_description' => 'White princess cassock for lady ministers, made to order in Nairobi. Festal dress for Easter, Christmas and weddings. Order for your church.', 'meta_keywords' => 'white princess cassock, ladies white cassock kenya, women clergy wear nairobi, festal cassock, easter clergy wear, white cassock dress, church robes kenya, clergy attire nairobi', 'og_title' => 'White Princes Cassock — Festal White for Women in Ministry', 'og_description' => 'The colour of Christmas, Easter and every celebration Sunday, cut on graceful princess seams and made to order in Nairobi. Chosen with reverence, delivered with care.']],
        'CLE-R-001' => ['short' => 'Bishopric rings in all sizes — the covenant band of a shepherd wedded in fidelity to the church and its people.', 'description' => '<p>The bishopric ring is often called the bishop’s wedding band — a sign of <strong>covenant fidelity</strong>, of a shepherd wedded to the church and to the people entrusted to his care. Placed on the hand at consecration, it is carried through every season of ministry thereafter.</p><p>Bethany House stocks <strong>bishopric rings in all sizes</strong>, so every hand — from a newly consecrated bishop to a long-serving overseer — finds a confident, comfortable fit.</p><ul><li>Available in all sizes</li><li>The traditional sign of covenant fidelity to the church</li><li>For bishops and senior clergy, including apostles and overseers</li><li>A moving consecration or enthronement gift</li></ul><p>Visit Sonalux House, Moi Avenue, Nairobi for a fitting, or order with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '💍', 'text' => 'Bishopric rings available in all sizes'], ['icon' => '🤝', 'text' => 'A sign of covenant fidelity — the bishop wedded to his church'], ['icon' => '⛪', 'text' => 'For bishops and senior clergy, including apostles and overseers'], ['icon' => '🎁', 'text' => 'A moving gift for consecrations and enthronements'], ['icon' => '📍', 'text' => 'Fitting available at Sonalux House, Moi Avenue, Nairobi'], ['icon' => '🌍', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['bishop ring', 'bishopric ring', 'episcopal ring', 'clergy ring', 'bishop\'s ring kenya', 'pete ya askofu', 'consecration ring', 'ring for bishops'], 'seo' => ['meta_title' => 'Bishopric Rings in All Sizes — Nairobi, Kenya', 'meta_description' => 'Bishopric rings in all sizes — the bishop\'s covenant band. Fitting at Sonalux House, Moi Avenue, Nairobi; delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'bishop ring kenya, bishopric ring nairobi, episcopal ring kenya, clergy ring nairobi, bishop regalia kenya, consecration ring, church supplies nairobi cbd, pete ya askofu', 'og_title' => 'Bishopric Rings in All Sizes — The Bishop\'s Covenant Band', 'og_description' => 'The bishop\'s wedding band — a sign of covenant fidelity to the church. All sizes at Bethany House, Sonalux House, Moi Avenue, Nairobi. Delivered worldwide.']],
        'CLE-RAC-001' => ['short' => 'Striking red apostolic cassock made to order in Nairobi — the colour of Pentecost fire, for apostles, bishops and church leaders.', 'description' => '<p>The cassock is the ankle-length daily garment of the clergy — and in red, it speaks. Red is the liturgical colour of Pentecost, of the Holy Spirit\'s fire and of the martyrs\' faithful witness, which is why apostolic and Pentecostal leaders often choose it as a bold mark of calling and office.</p><p>Each Red Apostolic Cassock is <strong>made to order in our Nairobi workshop</strong>, so it falls in a clean, dignified line from collar to hem — worn on its own or beneath other vestments.</p><p>A striking choice for apostles, bishops, overseers and ministers — for Pentecost, ordinations, consecrations and the red feasts of the church year.</p><ul><li>Made to order in our Nairobi workshop</li><li>Red — the colour of Pentecost and the Holy Spirit\'s fire</li><li>Worn alone or under other vestments</li><li>Delivery across Kenya and beyond</li></ul>', 'features' => [['icon' => '🔥', 'text' => 'Red — the liturgical colour of Pentecost, the Holy Spirit\'s fire and the martyrs\' witness'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop'], ['icon' => '👑', 'text' => 'A bold choice for apostles, bishops and Pentecostal church leadership'], ['icon' => '🙏', 'text' => 'Classic ankle-length cassock cut — worn on its own or beneath other vestments'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and beyond']], 'aliases' => ['red cassock', 'apostolic cassock', 'red clergy robe', 'pentecostal cassock', 'red soutane', 'bishop red cassock', 'red church robe', 'red cassok', 'red cassock price in kenya'], 'seo' => ['meta_title' => 'Red Apostolic Cassock — Tailored in Nairobi', 'meta_description' => 'Red apostolic cassock made to order in Nairobi — the colour of Pentecost for apostles and bishops. Delivery across Kenya and East Africa.', 'meta_keywords' => 'red cassock kenya, apostolic cassock, red clergy robe nairobi, pentecostal cassock, bishop red cassock, cassock price in kenya, clergy attire nairobi, red soutane, church robes kenya', 'og_title' => 'Red Apostolic Cassock — the Colour of Pentecost, Tailored in Nairobi', 'og_description' => 'The fire of Pentecost, tailored to your calling. Made to order in Nairobi for apostles, bishops and church leaders — chosen with reverence, delivered with care.']],
        'CLE-S-001' => ['short' => 'Made-to-measure canon gown tailored in Nairobi — robes worthy of an ACK canon\'s installation at the cathedral.', 'description' => '<p>Being made a canon is one of the great honours of Anglican ministry — an installation at the cathedral that recognises years of faithful service. The Bethany House <strong>Canon Gown</strong> is tailored for that honour: a stately gown cut to mark the office with the dignity it deserves.</p><p>Conventions for a canon\'s robes — colours, trims and detailing — vary from tradition to tradition and cathedral to cathedral, and our tailors will guide you on the convention your chapter follows. Every gown is made to measure in our Nairobi workshop at Sonalux House, Moi Avenue.</p><p>Serving ACK and Anglican clergy across Kenya and East Africa, with delivery worldwide. Order ahead of your installation and step into the cathedral fully robed for the office.</p>', 'features' => [['icon' => '✂️', 'text' => 'Made to measure in our Nairobi workshop at Sonalux House, Moi Avenue'], ['icon' => '🎨', 'text' => 'Colours and detailing tailored to the convention your cathedral follows'], ['icon' => '⛪', 'text' => 'For ACK and Anglican canons, installations and cathedral worship'], ['icon' => '📏', 'text' => 'Cut to your measurements for a stately, comfortable fit'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['canon gown kenya', 'ack canon robes', 'anglican canon gown', 'canon robes nairobi', 'cathedral robes kenya', 'installation robes', 'clergy gown kenya', 'canons gown'], 'seo' => ['meta_title' => 'Canon Gown — Tailored in Nairobi for ACK Canons', 'meta_description' => 'Canon gowns made to measure in Nairobi for ACK and Anglican clergy, cut to your cathedral\'s convention. Delivery across Kenya and East Africa.', 'meta_keywords' => 'canon gown kenya, ack canon robes, anglican canon gown nairobi, cathedral installation robes, clergy gowns kenya, made to measure canon gown, church robes nairobi', 'og_title' => 'Canon Gown — Robes Worthy of the Honour', 'og_description' => 'Tailored in Nairobi for ACK and Anglican canons: a made-to-measure gown cut to your cathedral\'s convention. Delivery across Kenya, East Africa and worldwide.']],
        'CLE-S-009' => ['short' => 'The badge of ordained ministry — a classic single-sided stole in your liturgical colour, tailored with reverence in Nairobi.', 'description' => '<p>The stole is the badge of ordained ministry — a long band worn over the shoulders, traditionally symbolising the yoke of Christ and the authority entrusted to those who teach and shepherd His people. Priests wear it around the neck, hanging down the front; deacons drape it over the left shoulder, joined at the right hip.</p><p>This classic single-sided stole is tailored in-house at our Nairobi workshop in the liturgical colour your season calls for — <strong>purple</strong> for Advent and Lent, <strong>white or gold</strong> for Christmas and Easter, <strong>red</strong> for Pentecost and ordinations, <strong>green</strong> for Ordinary Time.</p><p>A dignified choice for priests, pastors, reverends and deacons across Anglican, Catholic, Methodist, PCEA, Pentecostal and independent churches in Kenya and East Africa — and a treasured gift for a newly ordained minister.</p>', 'features' => [['icon' => '🕊️', 'text' => 'The badge of ordained ministry — symbol of the yoke of Christ'], ['icon' => '🎨', 'text' => 'Made in the full range of liturgical colours for every season of the church year'], ['icon' => '✂️', 'text' => 'Tailored in-house at our Nairobi workshop'], ['icon' => '⛪', 'text' => 'Worn across Anglican, Catholic, Methodist, PCEA and Pentecostal traditions'], ['icon' => '🎁', 'text' => 'A treasured gift for ordinations and ministry anniversaries'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['clergy stole', 'priest stole', 'liturgical stole', 'ordination stole', 'single side stole', 'deacon stole', 'reverend stole', 'church stole kenya', 'stole for pastors'], 'seo' => ['meta_title' => 'Single-Sided Clergy Stole in Nairobi, Kenya', 'meta_description' => 'Classic single-sided stoles in every liturgical colour, tailored in Nairobi. Delivered across Kenya, East Africa and worldwide. Order for your ministry.', 'meta_keywords' => 'clergy stole kenya, priest stole nairobi, liturgical stole, ordination stole kenya, single sided stole, deacon stole, clergy wear nairobi, church vestments kenya', 'og_title' => 'Single-Sided Stole — the Badge of Ordained Ministry', 'og_description' => 'One stole, worn at the altar and at the milestones of ministry. Tailored in Nairobi in your liturgical colour — chosen with reverence, delivered with care.']],
        'CLE-SC-001' => ['short' => 'A round bishop\'s skull cap — a quiet symbol of humility and reverence, made to your preference and head size.', 'description' => '<p>The <strong>skull cap</strong> — known in the Catholic tradition as the zucchetto — is the small round cap worn at the crown of a bishop’s head. It is a quiet symbol of <strong>humility and reverence before God</strong>, worn mostly in church ceremonies and liturgical processions.</p><p>In the classic convention its colour follows office — violet for bishops, black for priests, scarlet for cardinals, white reserved for the pope — a tradition our team is glad to guide you through.</p><p>Each cap is <strong>made according to your preference and head size</strong>, so it sits securely and comfortably through a full liturgy. Order from Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🎩', 'text' => 'Made according to your preference and head size'], ['icon' => '🙇', 'text' => 'A symbol of humility and reverence before God'], ['icon' => '🟣', 'text' => 'Colour traditionally follows office — our team will guide your choice'], ['icon' => '⛪', 'text' => 'Worn in church ceremonies and liturgical processions'], ['icon' => '🌍', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['zucchetto', 'zuchetto', 'bishop cap', 'bishops cap', 'calotte', 'skull cap kenya', 'clergy cap', 'purple skull cap'], 'seo' => ['meta_title' => 'Bishop\'s Skull Cap (Zucchetto) — Nairobi, Kenya', 'meta_description' => 'Bishop\'s skull caps made to your preference and head size — a symbol of humility and reverence. From Nairobi CBD, delivered across Kenya and worldwide.', 'meta_keywords' => 'bishop skull cap kenya, zucchetto nairobi, bishop cap kenya, clergy cap nairobi, zuchetto, calotte, bishop regalia kenya, church supplies nairobi cbd', 'og_title' => 'The Bishop\'s Skull Cap — Humility, Made to Fit', 'og_description' => 'A small round cap worn at the crown of the bishop\'s head — a quiet symbol of humility and reverence, made to your preference and head size at Bethany House, Nairobi.']],
        'CLE-UB-001' => ['short' => 'Uniform usher belt that sets your ushering team apart at the door — the ministry of first welcome, served in good order.', 'description' => '<p>Ushers are the first face of the congregation — the ministry of first welcome. A uniform usher belt identifies the team at a glance, so guests know exactly who to turn to and the service flows in good order, from the door to the offering (sadaka) to the final blessing.</p><p>Across Kenya and East Africa, a strong ushering department is a hallmark of a well-ordered church, with usher belts and sashes worn as a mark of order, hospitality and honour.</p><p>Outfit your whole department at once and let excellence begin at the entrance. Available at Sonalux House, Moi Avenue, Nairobi CBD, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🤝', 'text' => 'Instant identification for the ministry of first welcome'], ['icon' => '👥', 'text' => 'Uniforms the whole ushering department — order, hospitality, honour'], ['icon' => '⛪', 'text' => 'A hallmark of well-ordered congregations across Kenya and East Africa'], ['icon' => '🚚', 'text' => 'Order for the whole team — delivery across Kenya, East Africa and worldwide']], 'aliases' => ['usher sash', 'ushering belt', 'usher uniforms kenya', 'church usher belt', 'usher belts nairobi', 'hospitality team belt', 'protocol team belt'], 'seo' => ['meta_title' => 'Usher Belts & Sashes in Nairobi, Kenya', 'meta_description' => 'Uniform usher belts for church ushering teams — order, hospitality, honour. Outfit your department from Nairobi CBD; delivery across Kenya and beyond.', 'meta_keywords' => 'usher belts kenya, usher uniforms kenya, church usher sash nairobi, ushering department uniform, usher belt for church, church supplies nairobi cbd', 'og_title' => 'Usher Belts — The Ministry of First Welcome', 'og_description' => 'Uniform belts for your ushering team — order, hospitality and honour at the door. Delivered with care from Nairobi CBD.']],
        'CLE-WSN-001' => ['short' => 'Crisp white shirt with a normal collar — the clean foundation beneath a bib, cassock or clergy suit.', 'description' => '<p>Every clergy wardrobe rests on a good white shirt. The <strong>White Shirt – Normal</strong> is exactly that: a crisp white shirt with a standard collar, cut to sit cleanly beneath a bib (clergy rabat), a cassock or a suit — and to stand on its own wherever smart, simple dress is called for.</p><p>It is made to order in our Nairobi workshop at Sonalux House, Moi Avenue, so the fit is yours rather than off the rack. Pair it with our Bib and a detachable collar for the classic clerical front, or keep it as your dependable service shirt.</p><p>A quiet essential for pastors, elders, ushers, choirs and church workers across Kenya and East Africa, with delivery worldwide.</p>', 'features' => [['icon' => '⚪', 'text' => 'Crisp white shirt with a standard (normal) collar'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop, cut to your fit'], ['icon' => '🧥', 'text' => 'Sits cleanly under a bib, cassock or suit'], ['icon' => '🤝', 'text' => 'Serves clergy, elders, ushers, choirs and church workers'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['white clergy shirt', 'white shirt kenya', 'church shirt nairobi', 'plain white shirt clergy', 'shirt for bib', 'white shirt normal collar', 'ministers white shirt', 'clergy wear kenya'], 'seo' => ['meta_title' => 'White Clergy Shirt, Normal Collar — Nairobi', 'meta_description' => 'Crisp white shirts with a normal collar, made to order in Nairobi — the clean base for bibs, cassocks and suits. Delivery across Kenya.', 'meta_keywords' => 'white clergy shirt kenya, white shirt nairobi, clergy shirts kenya, shirt for clergy bib, church shirts nairobi, clergy wear kenya, ministers shirt kenya', 'og_title' => 'White Shirt (Normal Collar) — The Clergy Wardrobe Essential', 'og_description' => 'A crisp white shirt with a standard collar, tailored in Nairobi — the clean foundation beneath a bib, cassock or suit. Delivered across Kenya, East Africa and worldwide.']],
        'CLF-001' => ['short' => 'Tone-on-tone stoles with the motif carried in the same shade as the fabric — quiet elegance, made to order in Nairobi.', 'description' => '<p>"Self print" is the tailor\'s term for a pattern carried in the same tone as the base fabric — crosses and motifs that reveal themselves as the light moves, rather than announcing themselves. The result is a stole of quiet, unmistakable elegance.</p><p>Each self-print stole is made to order at our Nairobi workshop in the liturgical colour your season and tradition call for. The tone-on-tone finish sits beautifully over a plain cassock, alb or preaching gown without competing with your other vestments.</p><p>A refined choice for priests, pastors and reverends across Kenya and East Africa — for weekly services, ordinations and the festal days when understatement speaks loudest.</p>', 'features' => [['icon' => '✨', 'text' => 'Self-print finish — the motif woven in the same tone as the base fabric'], ['icon' => '🕊️', 'text' => 'Understated elegance that complements rather than competes'], ['icon' => '🧵', 'text' => 'Made to order at our Nairobi workshop'], ['icon' => '🎨', 'text' => 'Available in the liturgical colours of the church year'], ['icon' => '⛪', 'text' => 'Pairs beautifully with cassocks, albs and preaching gowns']], 'aliases' => ['self print stole', 'tone on tone stole', 'patterned clergy stole', 'textured stole', 'clergy stole design', 'priest stole nairobi', 'liturgical stole kenya', 'church stole nairobi'], 'seo' => ['meta_title' => 'Self-Print Clergy Stoles — Made to Order, Nairobi', 'meta_description' => 'Elegant tone-on-tone self-print stoles in every liturgical colour, made to order in Nairobi. Delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'self print stole kenya, tone on tone stole, clergy stole nairobi, patterned stole kenya, liturgical stole, priest stole price in kenya, vestments nairobi, clergy wear kenya', 'og_title' => 'Self-Print Stoles — Quiet Elegance for the Altar', 'og_description' => 'Motifs carried in the same tone as the fabric — stoles that reveal their beauty as the light moves. Made to order in Nairobi, delivered with care.']],
        'COL-GBT-001' => ['short' => 'Shallow gold-tone bread tray with a fitted lid — keeps communion bread dignified and dust-free from preparation to distribution.', 'description' => '<p>A shallow, round bread tray in a gleaming gold-tone finish, made to hold the communion bread or wafers before and during the service of Holy Communion. Its fitted lid keeps the elements dignified and dust-free from the preparation table to the altar.</p><p>This is the bread tray of the communion ware family — the flat plate for the bread, companion to the cup tray — carrying the elements to the congregation in an orderly, reverent manner, as your tradition directs.</p><ul><li><strong>Gold-tone finish</strong> that lends warmth and dignity to the Lord\'s table</li><li><strong>Fitted lid</strong> protects the bread from dust until the moment of distribution</li><li>Shallow, round form for easy, orderly serving along the rows</li><li>At home in Anglican, Catholic, Methodist, PCEA, Pentecostal and independent churches</li></ul><p>Chosen with reverence and delivered with care from Sonalux House, Moi Avenue, Nairobi — with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✨', 'text' => 'Gleaming gold-tone finish that honours the Lord\'s table'], ['icon' => '🍞', 'text' => 'Holds communion bread or wafers for orderly, reverent serving'], ['icon' => '🛡️', 'text' => 'Fitted lid keeps the bread dust-free until distribution'], ['icon' => '⛪', 'text' => 'Serves Anglican, Catholic, Methodist, PCEA and Pentecostal churches alike'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['communion bread plate', 'gold bread plate', 'bread plate', 'host plate', 'wafer tray', 'bread tray with lid', 'golden bread tray', 'sinia ya mkate', 'communion plate'], 'seo' => ['meta_title' => 'Gold Communion Bread Tray with Lid — Nairobi, Kenya', 'meta_description' => 'Gold-tone communion bread tray with fitted lid, from Sona