        'COM-AT-001' => ['short' => 'Light, durable aluminium communion tray for 40 cups with its own lid — 40 plastic cups included to start you serving.', 'description' => '<p>A light, durable aluminium communion tray that carries <strong>40 individual cups</strong>, with its own fitted lid to keep the cups covered, dust-free and protected from damage before the Lord\'s Supper.</p><p>Aluminium is the honest workhorse of communion ware — lighter in the servers\' hands than heavier metals and kinder to the budget, which makes this tray a faithful choice for church plants, growing fellowships and busy second services.</p><p>Every tray comes with <strong>40 plastic cups included</strong>, so your serving team is ready to serve straight from the box.</p><ul><li><strong>Carries 40 cups</strong>, each seated securely in the tray</li><li><strong>40 plastic cups included</strong> with every tray purchased</li><li><strong>Own fitted lid</strong> protects the cups from dust and damage before service</li><li>Durable, high-quality aluminium — light to carry along the rows</li></ul><p>From Sonalux House, Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍷', 'text' => 'Carries 40 individual communion cups'], ['icon' => '🎁', 'text' => '40 plastic cups included with every tray'], ['icon' => '🛡️', 'text' => 'Its own fitted lid keeps cups dust-free and protected from damage'], ['icon' => '🪶', 'text' => 'Lightweight, durable aluminium — easy to carry along the rows'], ['icon' => '💛', 'text' => 'A budget-kind choice for church plants and growing fellowships'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['aluminum communion tray', 'communion cup tray', '40 cup tray', 'communion tray with lid', 'affordable communion tray', 'communion trays kenya', 'aluminium cup tray', 'sinia'], 'seo' => ['meta_title' => 'Aluminium Communion Tray — 40 Cups, Kenya', 'meta_description' => 'Lightweight aluminium communion tray for 40 cups with lid — 40 plastic cups included. From Nairobi, delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'aluminium communion tray, aluminum communion tray, communion trays kenya, 40 cup communion tray, communion tray with lid, communion cups kenya, communion ware nairobi, church supplies nairobi', 'og_title' => 'Aluminium Communion Tray — 40 Cups, Lid and Cups Included', 'og_description' => 'Light, durable and budget-kind — a 40-cup aluminium tray with its own lid, plus 40 plastic cups included. From Nairobi, delivered worldwide.']],
        'COM-AW-001' => ['short' => 'Wine set apart for Holy Communion — the cup beside the bread at the Lord\'s Table, for churches across Kenya and East Africa.', 'description' => '<p>Altar wine — wine supplied for the Lord\'s Table. From the church\'s earliest days the cup has stood beside the bread at Holy Communion, and this wine is set apart for exactly that sacred use.</p><p>Pour it into the common cup or fill individual communion cups by the tray, as your tradition directs. It serves Anglican, Methodist, Pentecostal and independent congregations, as well as chaplaincies and pastors on home-communion rounds.</p><p>Pair it with communion cup trays, glasses and a refiller bottle from our communion ware range, and the Table is ready before the first hymn.</p><p>Chosen with reverence, delivered with care — from Bethany House, Sonalux House, Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍷', 'text' => 'Wine set apart for Holy Communion at the Lord\'s Table'], ['icon' => '⛪', 'text' => 'For Anglican, Methodist, Pentecostal and independent churches — as your tradition directs'], ['icon' => '🫗', 'text' => 'Suits both the common cup and individual communion cups in trays'], ['icon' => '🏠', 'text' => 'A faithful companion for home and hospital communion visits'], ['icon' => '🚚', 'text' => 'From Sonalux House, Moi Avenue, Nairobi — delivery across Kenya and East Africa']], 'aliases' => ['communion wine', 'church wine kenya', 'mass wine', 'sacramental wine', 'divai', 'mvinyo', 'alter wine', 'wine for holy communion', 'communion wine for churches'], 'seo' => ['meta_title' => 'Altar Wine for Churches in Kenya', 'meta_description' => 'Altar wine for Holy Communion — for the common cup or individual cups. Order for your church from Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'altar wine kenya, communion wine for churches kenya, church wine nairobi, where to buy altar wine in nairobi, sacramental wine, mass wine kenya, divai, communion supplies nairobi', 'og_title' => 'Altar Wine — The Cup Beside the Bread', 'og_description' => 'Wine set apart for the Lord\'s Table — for the common cup or individual communion cups, as your tradition directs. From Bethany House, Nairobi, delivered with care.']],
        'COM-D-001' => ['short' => 'Locally made sacramental communion wine from grapes, in a full 1-litre bottle — divai for the Lord\'s Table, by its Swahili name.', 'description' => '<p>Devai — a name that echoes <strong>divai</strong>, the word Swahili Scripture uses for wine in the story of the wedding at Cana. It is sacramental communion wine made from grapes, prepared for the celebration of Holy Communion.</p><p><strong>Locally made</strong> and bottled in a generous <strong>1-litre</strong> capacity, one bottle fills tray after tray of individual cups — practical provision for congregations that gather often at the Lord\'s Table.</p><p>A natural choice for Anglican, Methodist, Pentecostal and independent churches, and for pastors on home and hospital communion rounds — poured as your tradition directs.</p><p>From Bethany House at Sonalux House, Moi Avenue, Nairobi — serving churches across Kenya and East Africa, with worldwide delivery.</p>', 'features' => [['icon' => '🍇', 'text' => 'Sacramental communion wine made from grapes'], ['icon' => '🇰🇪', 'text' => 'Locally made — a dependable, close-to-home supply for the Lord\'s Table'], ['icon' => '🍷', 'text' => 'Generous 1-litre capacity fills tray after tray of individual cups'], ['icon' => '⛪', 'text' => 'Suits Anglican, Methodist, Pentecostal and independent communion services'], ['icon' => '🏠', 'text' => 'Practical for home and hospital communion visits'], ['icon' => '🚚', 'text' => 'From Bethany House, Nairobi — delivered across Kenya and East Africa']], 'aliases' => ['divai', 'communion wine', 'church wine kenya', 'altar wine', 'sacramental wine', 'mvinyo', 'divai ya ushirika', 'communion wine 1 litre', 'local communion wine'], 'seo' => ['meta_title' => 'Devai Communion Wine — 1 Litre, Kenya', 'meta_description' => 'Devai — locally made sacramental communion wine from grapes, in a 1-litre bottle. Order for your church from Bethany House, Nairobi; delivery across Kenya.', 'meta_keywords' => 'communion wine kenya, church wine nairobi, devai communion wine, divai, sacramental wine kenya, altar wine for churches, communion wine 1 litre, mvinyo wa ushirika, where to buy communion wine nairobi', 'og_title' => 'Devai — Locally Made Communion Wine, 1 Litre', 'og_description' => 'Divai for the Lord\'s Table — locally made sacramental communion wine from grapes, in a generous 1-litre bottle. From Bethany House, Nairobi, chosen with reverence.']],
        'COM-I-001' => ['short' => 'Frankincense church incense for the thurible — fragrant smoke that has pictured prayer rising before God since ancient days.', 'description' => '<p>Frankincense — the fragrant resin of the Boswellia tree, carried by the Magi and burned in worship ever since. Spooned onto glowing charcoal in a chain-swung thurible (also called a censer), it releases the sweet smoke in which the church has long seen a picture of prayer rising before God.</p><p>Incense graces the liturgy in Catholic, Orthodox and Anglican high-church worship — at solemn celebrations and Benediction, in processions and funerals, and at the blessing of churches and homes. Across Kenya many simply ask for it by its Kiswahili name: <strong>ubani</strong>.</p><p>Burn with self-lighting charcoal in your thurible or censer — a little goes a long way, and the fragrance fills the whole sanctuary.</p><p>Chosen with reverence, delivered with care — from Bethany House, Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🔥', 'text' => 'Frankincense resin for church use — burn on charcoal in a thurible or censer'], ['icon' => '🙏', 'text' => 'The fragrance the church has long read as prayer rising before God'], ['icon' => '⛪', 'text' => 'For solemn liturgies, Benediction, processions, funerals and blessings of homes'], ['icon' => '🌍', 'text' => 'Known across Kenya by its Kiswahili name, ubani'], ['icon' => '🚚', 'text' => 'Delivery across Kenya, East Africa and worldwide from Nairobi CBD']], 'aliases' => ['ubani', 'uvumba', 'frankincense', 'church incense', 'incense for thurible', 'censer incense', 'altar incense', 'olibanum', 'incense resin', 'chetezo incense'], 'seo' => ['meta_title' => 'Church Incense (Frankincense) in Kenya', 'meta_description' => 'Frankincense incense for the thurible — ubani for solemn liturgies, processions and blessings. From Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'church incense kenya, ubani, frankincense nairobi, incense for church, thurible incense, censer incense, altar incense kenya, catholic church incense, uvumba, church supplies nairobi', 'og_title' => 'Frankincense Church Incense — Ubani for the Thurible', 'og_description' => 'Frankincense for worship — the resin of the Boswellia tree, burned on charcoal in the thurible as prayer rises. From Bethany House, Nairobi, delivered across Kenya and beyond.']],
        'COM-LC-001' => ['short' => 'A generously sized chalice in golden or silver finish — made for large congregations, concelebrations and the common cup.', 'description' => '<p>When the congregation is many and the feast is great, the altar calls for a chalice of generous measure. This large chalice holds the communion wine for the Holy Eucharist and the partaking of Holy Communion, and recalls the cup of the Last Supper which Jesus shared with His disciples.</p><p>It is offered in two finishes — golden and silver — so it can match the rest of your altar ware. The larger cup suits cathedrals and big parishes, concelebrated services, and Anglican congregations that share a common cup.</p><ul><li>Generous size for <strong>large congregations</strong> and concelebrations</li><li>Available in golden or silver finish</li><li>Classic cup, stem and foot form for confident handling before the assembly</li><li>Care: hand-wash and dry immediately with a soft, lint-free cloth</li></ul><p>Serving Anglican (ACK), Catholic, Methodist, PCEA, Pentecostal and independent churches — from Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍷', 'text' => 'Generous capacity for large congregations, concelebrations and the shared common cup'], ['icon' => '🎨', 'text' => 'Offered in two finishes — golden or silver — to match your altar ware'], ['icon' => '✝️', 'text' => 'Recalls the cup of the Last Supper which Jesus shared with His disciples'], ['icon' => '✋', 'text' => 'Classic cup, stem and foot form for confident handling before the assembly'], ['icon' => '🚚', 'text' => 'From Nairobi CBD — delivery across Kenya, East Africa and worldwide']], 'aliases' => ['large communion chalice', 'big chalice', 'concelebration chalice', 'silver chalice', 'golden chalice', 'common cup chalice', 'chalice for large church'], 'seo' => ['meta_title' => 'Large Chalice for Churches — Nairobi, Kenya', 'meta_description' => 'Large communion chalice in golden or 