        'COM-PC-001' => ['short' => 'Light, hygienic plastic cups made for communion trays — quick to fill, easy to serve at gatherings of any size.', 'description' => '<p>Light plastic cups made for communion trays — the practical way to serve the Lord\'s Supper when the congregation is large and the moment must flow without hurry.</p><p>Each member receives an individual cup, which keeps the service hygienic and orderly; and because they are light, these cups travel well to crusades, outdoor services, home fellowships and hospital visits. Deacons and serving teams fill them ahead of the service, and the trays move smoothly along the rows.</p><ul><li>Made to sit in <strong>communion trays</strong> for orderly serving</li><li>Individual cups — a hygienic way for every member to receive</li><li>Light to carry: ideal for large services, crusades and outreach</li><li>Quick for serving teams to fill and distribute</li></ul><p>Order for your church from Sonalux House, Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍇', 'text' => 'Made to sit in communion trays for smooth, orderly serving'], ['icon' => '🧼', 'text' => 'Hygienic individual cups — every member receives their own'], ['icon' => '🪶', 'text' => 'Light to carry — ideal for crusades, outdoor services and home visits'], ['icon' => '⚡', 'text' => 'Quick for deacons and serving teams to fill and distribute'], ['icon' => '🚚', 'text' => 'From Sonalux House, Moi Avenue, Nairobi — delivery across Kenya and worldwide']], 'aliases' => ['disposable communion cups', 'plastic communion glasses', 'communion cups for trays', 'single use communion cups', 'communion cups kenya', 'vikombe vya ushirika', 'tray communion cups', 'communion wares'], 'seo' => ['meta_title' => 'Plastic Communion Cups in Nairobi, Kenya', 'meta_description' => 'Light, hygienic plastic cups made for communion trays — ideal for large services and crusades. From Nairobi, delivered across Kenya and worl