        'COM-PCC-001' => ['short' => 'Sealed single-serve communion — one bread and 10ml of wine in one hygienic package, ready for services, visits and crusades.', 'description' => '<p>Each pre-packed cup carries both elements of the Lord\'s Supper in one sealed, single-serve package — <strong>one communion bread</strong> on one part and <strong>10ml of wine</strong> on the other. One cup, one communicant, once.</p><p>There are no trays to fill and nothing to wash afterwards: open, partake, and dispose. That makes these cups a quiet blessing for hospital and home visits, large crusades and outdoor gatherings, travel, and congregations that prize hygiene at the table.</p><ul><li>Both elements in one sealed package — bread and 10ml of wine</li><li>Single-use and hygienic — each cup serves one person</li><li>No filling and no washing-up, even for the largest gatherings</li><li>Ideal for hospital visits, home communion, crusades and travel</li></ul><p>From Sonalux House, Moi Avenue, Nairobi — order for your church with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✝️', 'text' => 'Bread and 10ml of wine sealed together in one single-serve cup'], ['icon' => '🧼', 'text' => 'Hygienic single use — one cup, one communicant'], ['icon' => '🏥', 'text' => 'Ideal for hospital and home visits, crusades and travel'], ['icon' => '⏱️', 'text' => 'No trays to fill and nothing to wash after the service'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['prefilled communion cups', 'pre-filled communion cups', 'sealed communion cups', 'all in one communion cups', 'communion sets', 'prefilled cups kenya', 'communion elements', 'travel communion set', 'ushirika mtakatifu'], 'seo' => ['meta_title' => 'Prefilled Communion Cups in Nairobi, Kenya', 'meta_description' => 'Sealed single-serve communion cups — bread and wine in one hygienic package. Ideal for visits and crusades. Delivery across Kenya 