        'COM-PO-001' => ['short' => 'Unleavened communion wafer bread, 500 pieces per pack — a faithful staple for the Lord\'s Table in growing congregations.', 'description' => '<p>Unleavened wafer bread for Holy Communion — the element the Western church has set on the Lord\'s Table for centuries. Each thin wafer breaks and hands out cleanly, letting the congregation receive with order and reverence, as your tradition directs.</p><p>This pack holds <strong>500 pieces</strong> — a dependable staple for mid-size congregations and for churches that gather at the Lord\'s Supper every month.</p><ul><li>500 wafers per pack</li><li>Unleavened, in the Western communion tradition</li><li>Suits bread trays, patens and full communion sets</li><li>Store airtight in a cool, dry place; handle with dry hands</li></ul><p>Chosen with reverence, delivered with care — from Bethany House at Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍞', 'text' => 'Unleavened wafer bread in the Western tradition of the Lord\'s Table'], ['icon' => '📦', 'text' => '500 pieces per pack — a dependable staple for mid-size congregations'], ['icon' => '✝️', 'text' => 'Serves Anglican, Methodist, PCEA, Pentecostal and independent communion services alike'], ['icon' => '🤲', 'text' => 'Thin wafers that break and distribute cleanly from bread tray or paten'], ['icon' => '🫙', 'text' => 'Keeps well in an airtight container in a cool, dry place'], ['icon' => '🚚', 'text' => 'Delivery across Kenya, East Africa and worldwide from Nairobi CBD']], 'aliases' => ['communion wafers', 'communion bread', 'altar bread', 'mkate wa ushirika', 'communion wafers 500 pieces', 'lords supper bread', 'communion elements', 'wafer bread kenya', 'holy communion wafers'], 'seo' => ['meta_title' => 'Communion Wafer Bread 500 Pcs — Kenya', 'meta_description' => 'Unleavened communion wafer bread, 500 pieces per pack. Order for your church from Bethany House, Nai