        'COM-R-001' => ['short' => 'The deacon\'s quiet helper — a squeeze bottle that fills each communion cup with 10–15ml of wine, without a drop on the linen.', 'description' => '<p>Every serving team knows the moment: row upon row of small cups to fill and white linen daring you to spill. The refiller is the humble answer — a squeeze bottle that dispenses <strong>10ml–15ml into each cup</strong>, quickly, cleanly and without a single splash.</p><p>Fill the bottle with communion wine or grape juice as your tradition directs, then a gentle squeeze charges cup after cup in the tray. Preparation that once took long minutes becomes a calm, orderly rhythm before the service begins.</p><ul><li>Dispenses <strong>10ml–15ml per cup</strong></li><li>Squeeze action fills tray cups quickly and without spillage</li><li>Works with communion wine or grape juice alike</li><li>Spares the linen — and the deacons\' nerves</li></ul><p>A quiet essential of communion ware, from Sonalux House, Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '💧', 'text' => 'Dispenses 10ml–15ml of wine into each cup'], ['icon' => '🤲', 'text' => 'Gentle squeeze action — fills tray cups quickly, without spills'], ['icon' => '🍷', 'text' => 'Works with communion wine or grape juice, as your tradition directs'], ['icon' => '🧺', 'text' => 'Spares the linen and calms preparation before service'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['communion cup filler', 'wine filler bottle', 'cup filling bottle', 'squeeze bottle for communion', 'communion wine dispenser', 'refilling bottle', 'communion accessories nairobi'], 'seo' => ['meta_title' => 'Communion Cup Filler Bottle — Nairobi, Kenya', 'meta_description' => 'Squeeze-bottle refiller filling each communion cup with 10–15ml of wine — quick, clean, no spills. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'communion cu