        'CWIZIB1ZL' => ['short' => 'Compact 200-piece communion wafer pack — a quick online restock between bulk orders, ready for your next service.', 'description' => '<p>A compact <strong>200-piece</strong> pack of communion wafers — the easy restock that keeps the Lord\'s Table supplied without overfilling the vestry cupboard. Order fresh, serve fresh.</p><p>Unleavened in the Western tradition of Holy Communion, these thin wafers break and hand out cleanly, sitting naturally on a bread tray or paten alongside your existing communion ware.</p><p>A practical choice for midweek and evening services, cell-group communion, youth fellowships and congregations that prefer smaller, more frequent orders. Store airtight in a cool, dry place and handle with dry hands, as with all communion bread.</p><p>Chosen with reverence, delivered with care — from Bethany House, Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍞', 'text' => 'Unleavened communion wafers in the Western tradition of the Lord\'s Supper'], ['icon' => '📦', 'text' => 'Compact 200-piece pack — order fresh, serve fresh'], ['icon' => '🕯️', 'text' => 'Handy for midweek services, cell groups and youth fellowships'], ['icon' => '🤲', 'text' => 'Thin wafers that break and distribute cleanly from tray or paten'], ['icon' => '🚚', 'text' => 'Quick delivery across Kenya and East Africa from Nairobi CBD']], 'aliases' => ['communion wafers', 'communion bread', 'wafer bread 200', 'altar bread', 'mkate wa ushirika', 'small communion wafer pack', 'lords supper wafers', 'communion elements kenya'], 'seo' => ['meta_title' => 'Buy Communion Wafers 200 Pcs Online, Kenya', 'meta_description' => 'Communion wafers in a compact 200-piece pack — an easy restock for your church. Bethany House, Nairobi; delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'communion wafers kenya, buy communion wafers online kenya, communion bread nairobi, wafer bread for churches, communion elements kenya, midweek communion supplies, mkate wa ushirika, church supplies nairobi cbd', 'og_title' => 'Communion Wafers — Compact 200-Piece Pack', 'og_description' => 'A 200-piece pack of unleavened communion wafers — the easy restock for midweek services and cell-group communion. From Bethany House, Nairobi, delivered with care.']],
        'FBU30QUE0' => ['short' => 'Classic white cassock made in Kenya by Bethany House — for clergy, worship leaders and choirs, worn alone or under a surplice.', 'description' => '<p>The white cassock is worn by clergy and lay worship leaders alike, with or without a surplice — a garment most at home in Anglican, Roman Catholic and Orthodox churches, and a beloved choice for choirs, many of whom wear cassock and surplice in place of robes.</p><p>In white, the cassock carries the festal brightness of the church\'s great celebrations, and it suits our warm climate: cool, clean and dignified through long services and processions.</p><p>This cassock is <strong>made in Kenya by Bethany House</strong> with great care and quality control.</p><p>Wear it on its own, under a surplice for choir offices, or as the base of fuller vestments in festal seasons.</p>', 'features' => [['icon' => '🇰🇪', 'text' => 'Made in Kenya by Bethany House with great care and quality control'], ['icon' => '⛪', 'text' => 'At home in Anglican, Roman Catholic and Orthodox worship'], ['icon' => '🎶', 'text' => 'Pairs with a surplice — a beloved choice for choirs and choir offices'], ['icon' => '☀️', 'text' => 'White festal brightness, cool and dignified in warm East African climates'], ['icon' => '🙏', 'text' => 'Worn by clergy and lay worship leaders alike']], 'aliases' => ['white clergy robe', 'white soutane', 'choir cassock', 'white church robe', 'cassock and surplice', 'white kanzu', 'white casock', 'anglican white cassock'], 'seo' => ['meta_title' => 'White Cassock — Made in Kenya', 'meta_description' => 'Classic white cassock made in Kenya by Bethany House — for clergy, worship leaders and choirs. Chosen with reverence, delivered across Kenya and beyond.', 'meta_keywords' => 'white cassock kenya, choir cassock nairobi, cassock and surplice, white clergy robe, anglican cassock kenya, catholic cassock nairobi, made in kenya cassock, church robes kenya', 'og_title' => 'White Cassock — Made in Kenya