        'FBU30QUE0-499E' => ['short' => 'Eliad anointing oil — set apart for prayer, blessing and consecration after James 5:14, for pastors and prayer teams alike.', 'description' => '<p>Eliad anointing oil is kept for the moments when prayer becomes visible. In Scripture, kings and priests were set apart with oil, and James 5:14 calls the elders of the church to pray over the sick and anoint them with oil in the name of the Lord.</p><p>Keep it ready for anointing in services and home visits, the consecration of ministries and leaders, and the blessing of homes, businesses and those setting out on new seasons — used as your tradition directs.</p><p>A staple for pastors, chaplains, intercessors and prayer teams across Catholic, Anglican, Pentecostal and independent churches alike.</p><p>Chosen with reverence, delivered with care — from Bethany House, Sonalux House, Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🙏', 'text' => 'Eliad anointing oil, set apart for prayer, blessing and consecration'], ['icon' => '📖', 'text' => 'In Scripture, oil sets apart kings, priests and people of prayer'], ['icon' => '🤲', 'text' => 'For prayer over the sick after James 5:14 — anointing in the name of the Lord'], ['icon' => '🏠', 'text' => 'For consecration and the blessing of homes, businesses and ministries'], ['icon' => '⛪', 'text' => 'Welcome across traditions — Catholic, Anglican, Pentecostal and independent'], ['icon' => '🚚', 'text' => 'From Bethany House, Nairobi — delivered across Kenya, East Africa and worldwide']], 'aliases' => ['mafuta ya upako', 'annointing oil', 'anointing oil', 'prayer oil', 'consecration oil', 'holy anointing oil', 'eliad oil'], 'seo' => ['meta_title' => 'Eliad Anointing Oil — Nairobi, Kenya', 'meta_description' => 'Eliad anointing oil for prayer, blessing and consecration. Order from Bethany House, Nairobi — delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'anointing oil kenya, eliad