        'GEN-NJB-001' => ['short' => 'The New Joy Bible — a children\'s Bible in blue or pink, full of pictorial illustrations that entice a child\'s interest in reading.', 'description' => '<p>The <strong>New Joy Bible</strong> is a children\'s Bible designed to make a child want to open it: bright pictorial illustrations sit alongside the text, drawing young readers in and enticing their interest in reading God\'s Word for themselves.</p><ul><li>A children\'s Bible made for young readers</li><li>Pictorial illustrations that entice a child\'s interest in reading</li><li>Available in two covers — blue and pink</li><li>A lovely gift for birthdays, baptisms and Sunday-school graduations</li></ul><p>Choose blue or pink and make it the <strong>first Bible</strong> a child calls their own — a keepsake gift they will treasure as they grow.</p><p>Chosen with reverence, delivered with care — from Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📖', 'text' => 'A children\'s Bible made for young readers'], ['icon' => '🎨', 'text' => 'Pictorial illustrations that entice a child\'s interest in reading'], ['icon' => '📘', 'text' => 'Available in blue and pink covers'], ['icon' => '🎁', 'text' => 'A lovely first-Bible, birthday and Sunday-school gift']], 'aliases' => ['new joy bible', 'joy bible blue', 'joy bible pink', 'children bible kenya', 'kids bible nairobi', 'biblia ya watoto', 'first bible for child', 'childrens bible blue pink'], 'seo' => ['meta_title' => 'New Joy Children\'s Bible — Blue & Pink, Kenya', 'meta_description' => 'The New Joy Bible — a children\'s Bible in blue or pink with pictorial illustrations that spark a love of reading. Delivered across Kenya and worldwide.', 'meta_keywords' => 'joy children bible, new joy bible kenya, kids bible nairobi, children bible blue pink, baptism gift kenya, first bible child, biblia ya watoto, childrens bible kenya', 'og_title' => 'New Joy Bible — A Child\'s Own Bible', 'og_description' => 'Bright pictorial illustrations that entice a child to read — the New Joy Bible in blue or pink, delivered from Nairobi across Kenya, East Africa and worldwide.']],
        'GEN-PO-001' => ['short' => 'Wafer bread for Holy Communion in a handy 200-piece pack — right-sized for chapels, fellowships and home communion visits.', 'description' => '<p>Wafer bread for Holy Communion in a right-sized <strong>200-piece</strong> pack — enough for chapels, school and hospital chaplaincies, fellowship groups and home communion visits, without keeping more stock than you need.</p><p>Unleavened in the Western tradition of the Lord\'s Supper, these wafers serve Anglican, Methodist, PCEA, Pentecostal and independent congregations alike — received as your tradition directs.</p><p>Keep the pack in an airtight container in a cool, dry place and handle the wafers with dry hands, and they will stay ready for the next time your people gather at the Table. From Bethany House at Sonalux House, Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍞', 'text' => 'Unleavened wafer bread for the Lord\'s Supper, in the Western tradition'], ['icon' => '📦', 'text' => '200 pieces — right-sized for chapels, fellowships and smaller congregations'], ['icon' => '🏥', 'text' => 'Ideal for chaplaincies and home or hospital communion visits'], ['icon' => '✝️', 'text' => 'At home in Anglican, Methodist, PCEA, Pentecostal and independent services'], ['icon' => '🫙', 'text' => 'Keeps well airtight in a cool, dry place until the day of service'], ['icon' => '🚚', 'text' => 'From Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide']], 'aliases' => ['communion bread', 'communion wafers', 'wafer bread', 'altar bread', 'mkate wa ushirika', 'communion bread 200 pieces', 'small pack communion wafers', 'lords supper bread'], 'seo' => ['meta_title' => 'Communion Bread 200 Pcs — Nairobi, Kenya', 'meta_description' => 'Wafer bread for Holy Communion, 200 pieces per pack — right-sized for chapels and fellowships. Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'communion bread kenya, communion wafers nairobi, wafer bread for communion, altar bread kenya, small communion bread pack, mkate wa ushirika, home communion supplies, church supplies nairobi', 'og_title' => '200 Pieces of Communion Bread — Right-Sized for Your Fellowship', 'og_description' => 'Unleavened wafer bread for Holy Communion in a handy 200-piece pack — perfect for chapels, fellowships and home visits. From Bethany House, Nairobi, delivered with care.']],
        'GEN-S-001' => ['short' => 'The aspergillum — a holy water sprinkler for blessing congregation, altar and home, used in the Asperges rite and baptisms.', 'description' => '<p>The holy water sprinkler — known in the liturgy as the <strong>aspergillum</strong> — is the vessel by which blessing is scattered. The priest dips it in the holy water bucket, the aspersorium, and sprinkles the congregation, the altar, or objects set apart for God.</p><p>It leads the Asperges at the start of worship, blesses homes and the households within them, consecrates objects for sacred use, and recalls baptism every time the water flies. It is at home in Catholic, Anglican and Orthodox services alike.</p><ul><li>Sprinkles holy water over people, altars and objects of devotion</li><li>Pairs naturally with an aspersorium (holy water bucket)</li><li>For the Asperges rite, baptismal remembrance and house blessings</li><li>Used across Catholic, Anglican and Orthodox traditions</li></ul><p>Chosen with reverence, delivered with care — from Sonalux House, Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '💦', 'text' => 'Scatters holy water over congregation, altar and sacred objects'], ['icon' => '⛪', 'text' => 'For the Asperges rite, baptism remembrance and house blessings'], ['icon' => '🪣', 'text' => 'Pairs naturally with an aspersorium — dip and sprinkle'], ['icon' => '✝️', 'text' => 'At home in Catholic, Anglican and Orthodox worship'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['aspergillum', 'holy water sprinkler', 'holy water shaker', 'asperges sprinkler', 'church water sprinkler', 'blessing sprinkler', 'aspergilum', 'water sprinkler for church'], 'seo' => ['meta_title' => 'Holy Water Sprinkler (Aspergillum) — Kenya', 'meta_description' => 'Aspergillum holy water sprinkler for the Asperges, baptisms and house blessings. From Sonalux House, Nairobi — delivery across Kenya and worldwide.', 'meta_keywords' => 'holy water sprinkler, aspergillum, aspersorium, holy water sprinkler kenya, church supplies nairobi, asperges, baptism blessing, catholic church supplies kenya, anglican church supplies', 'og_title' => 'Holy Water Sprinkler — The Aspergillum', 'og_description' => 'The vessel by which blessing is scattered — for the Asperges, baptisms and house blessings. Chosen with reverence, delivered across Kenya and worldwide.']],
        'GOW-C-001' => ['short' => 'Italian hand-made liturgical chasuble in 100% polyester with golden cross embellishment — artisan quality for the celebrant.', 'description' => '<p>The chasuble is the principal vestment of the celebrant at the Mass or Eucharist, worn over alb and stole. This liturgical chasuble is entirely hand-made in Italy by an artisan company with years of experience — a garment that carries tradition and beauty in every seam.</p><p>It is cut in <strong>100% polyester</strong> and finished with a <strong>golden crosses embellishment</strong> — the fabric accurately chosen, and the making carried out with competence, passion and innovation.</p><p>An elegant choice for Catholic, Anglican and Methodist celebrants across Kenya and East Africa who want imported artisan quality at the altar — for Sunday Eucharist, festal celebrations and the great feasts of the church year.</p>', 'features' => [['icon' => '🇮🇹', 'text' => 'Entirely hand-made in Italy by an artisan company with years of experience'], ['icon' => '✝️', 'text' => 'Finished with a golden crosses embellishment'], ['icon' => '🧵', 'text' => '100% polyester, with the fabric accurately chosen'], ['icon' => '🕊️', 'text' => 'Made following tradition and beauty — a high-quality celebrant\'s vestment'], ['icon' => '⛪', 'text' => 'For Catholic, Anglican and Methodist Eucharistic celebrants'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['italian chasuble', 'chasuble with golden crosses', 'priest chasuble kenya', 'catholic chasuble nairobi', 'imported chasuble', 'mass vestment', 'chausable', 'chasuble price in kenya'], 'seo' => ['meta_title' => 'Italian Chasuble with Golden Crosses — Kenya', 'meta_description' => 'Liturgical chasuble hand-made in Italy — 100% polyester with golden cross embellishment. Available in Nairobi, delivered across Kenya and worldwide.', 'meta_keywords' => 'italian chasuble kenya, chasuble nairobi, catholic chasuble, golden 