        'GOW-C-001-D71C' => ['short' => 'A bishop\'s ceremonial cope in purple and red, finished with a mint body and self-print front — made to order in Nairobi.', 'description' => '<p>The cope is the church\'s great processional cape — long, open at the front and fastened across the chest, worn for the rites where solemnity matters most. This cope joins two colours rich in meaning: <strong>purple</strong>, the colour long associated with bishops, penitence and royalty, and <strong>red</strong>, the colour of Pentecost fire, ordinations and the martyrs\' witness.</p><p>This particular design is finished with a <strong>mint body</strong> and a <strong>self-print front</strong> — a tone-on-tone pattern carried in the fabric itself. Made to order at our Nairobi workshop, it is cut for bishops and senior clergy who lead ordinations, confirmations, processions and the solemn seasons of the church year.</p><p>Serving Anglican, Catholic, Methodist, Pentecostal and independent church leadership across Kenya and East Africa — a garment equal to the office it clothes.</p>', 'features' => [['icon' => '💜', 'text' => 'Purple — the colour long associated with the episcopal office'], ['icon' => '❤️', 'text' => 'Red — the colour of Pentecost, ordinations and the martyrs\' witness'], ['icon' => '✨', 'text' => 'Finished with a mint body and a self-print front'], ['icon' => '👑', 'text' => 'Cut for bishops and senior clergy'], ['icon' => '✂️', 'text' => 'Made to order at our Nairobi workshop'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['purple cope', 'red cope', 'bishop cope purple', 'bishops cape kenya', 'ceremonial cope nairobi', 'cope for bishops', 'bishop regalia', 'processional cape'], 'seo' => ['meta_title' => 'Purple & Red Bishop\'s Cope — Nairobi, Kenya', 'meta_description' => 'A bishop\'s cope in purple and red with a mint body and self-print front — made to order in Nairobi. Delivered across Kenya and East Africa.', 'meta_keywords' => 'purple cope kenya, bishop cope nairobi, red cope, bishop regalia kenya, ordination cope, bishops vestments nairobi, ceremonial cape kenya, clergy vestments kenya', 'og_title' => 'Purple & Red Cope — For the Episcopal Office', 'og_description' => 'Purple for the bishop\'s office, red for the fire of ordination — one ceremonial cope, made to order in Nairobi and delivered with care across East Africa.']],
        'IXOYNZQG8-A1DA' => ['short' => 'Ceremonial worship horn in the shofar tradition — sounded for calls to worship, repentance and celebration (Joel 2:1).', 'description' => '<p>The horn carries one of Scripture\'s oldest sounds. <strong>"Blow the shofar in Zion"</strong> (Joel 2:1) — from the walls of Jericho to the watchmen on Israel\'s towers, the horn has summoned God\'s people to worship, repentance and readiness in prayer.</p><p>Traditionally a ram\'s horn — or, in the long spiralled Yemenite style, a kudu horn — the shofar has found a powerful home in charismatic and Pentecostal worship, and it resonates deeply in Kenya\'s prophetic and intercessory gatherings: sounding the call at conferences, crusades, overnight kesha vigils and new-season declarations.</p><p>A striking and meaningful instrument for worship leaders, intercessors and prophetic ministries — and a memorable gift for an ordination or commissioning. Chosen with reverence at Sonalux House, Moi Avenue, Nairobi, and delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📯', 'text' => 'Sounds the biblical call of Joel 2:1 — "Blow the shofar in Zion"'], ['icon' => '🙏', 'text' => 'Beloved in charismatic, Pentecostal and prophetic worship across Kenya'], ['icon' => '🎺', 'text' => 'For calls to worship, repentance, intercession and celebration'], ['icon' => '🎁', 'text' => 'A meaningful gift for worship leaders, ordinations and commissionings'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['shofar', 'ram\'s horn', 'kudu horn', 'worship horn', 'trumpet horn', 'baragumu', 'shofar for sale nairobi', 'yemenite shofar', 'prophetic horn', 'shofar kenya'], 'seo' => ['meta_title' => 'Shofar Worship Horn in Nairobi, Kenya', 'meta_description' => 'Ceremonial shofar-style worship horn for calls to worship and intercession. Order from Sonalux House, Nairobi — delivery across Kenya and worldwide.', 'meta_keywords' => 