        'KU5ZE5ZFY' => ['short' => 'Plain round white communion wafers, 1 1/8 in. across, in airtight boxes — 1000 pieces for large congregations and big days.', 'description' => '<p>For churches who prefer white unleavened bread at the Lord\'s Table, these plain round communion wafers measure <strong>1 1/8 inch</strong> across — the size long favoured for the congregation — and arrive packed in airtight boxes that keep them ready until the day of service.</p><p>Each box serves <strong>1000 pieces</strong>: generous provision for large congregations, conventions and crusades, and for churches that celebrate Holy Communion every week.</p><ul><li>White unleavened bread, plain round wafers</li><li>1 1/8 inch across — congregation size</li><li>1000 pieces per airtight box</li><li>Distributes cleanly at the rail or by bread tray</li></ul><p>From Bethany House at Sonalux House, Moi Avenue, Nairobi — serving churches across Kenya and East Africa, with worldwide delivery.</p>', 'features' => [['icon' => '🍞', 'text' => 'White unleavened communion wafers — plain, round, 1 1/8 inch across'], ['icon' => '📦', 'text' => '1000 pieces per airtight box — provision for large congregations'], ['icon' => '⛪', 'text' => 'Ready for conventions, crusades and churches serving communion weekly'], ['icon' => '🤲', 'text' => 'Congregation-size wafers that distribute cleanly at the rail or by tray'], ['icon' => '🫙', 'text' => 'Airtight packaging keeps the wafers ready until the day of service'], ['icon' => '🚚', 'text' => 'From Bethany House, Nairobi — delivered across Kenya, East Africa and worldwide']], 'aliases' => ['communion wafers 1000', 'communion bread', 'altar bread', 'bulk communion wafers', 'mkate wa ushirika', 'unleavened communion bread', 'church wafers kenya', 'communion elements', 'white communion wafers'], 'seo' => ['meta_title' => 'Holy Communion Bread 1000 Pcs — Kenya', 'meta_description' => 'White unleavened communion wafers, 1 1/8 in., 1000 pieces in airtight boxes. Order from Bethany House, Nairobi — delivery across Kenya and worldwide.', 'meta_keywords' => 'holy communion bread kenya, communion wafers 1000 pieces, bulk communion wafers nairobi, altar bread suppliers kenya, unleavened communion bread, communion elements kenya, church supplies nairobi, mkate wa ushirika', 'og_title' => 'Holy Communion Bread — 1000 Wafers, Packed Airtight', 'og_description' => 'Plain round white communion wafers, 1 1/8 inch across, 1000 pieces per airtight box — provision for large congregations. From Bethany House, Nairobi, delivered with care.']],
        'M3BXRUQJC' => ['short' => 'Canon gown tailored in Nairobi for Catholic fathers — made-to-measure choir dress for canons and cathedral clergy.', 'description' => '<p>This <strong>Canon Gown</strong> is tailored with Catholic fathers in mind — priests honoured as canons of a cathedral or collegiate chapter, and clergy who take their place in choir dress for solemn celebrations. It is a garment of office: worn over the cassock, it marks rank and years of service to the Church.</p><p>Every gown is made to measure in our Nairobi workshop at Sonalux House, Moi Avenue. Our tailors will advise on the colour and detailing appropriate to your appointment and your diocese\'s custom.</p><p>Serving Catholic clergy across Kenya and East Africa, with delivery worldwide. Chosen with reverence, delivered with care.</p>', 'features' => [['icon' => '✂️', 'text' => 'Made to measure in our Nairobi workshop at Sonalux House, Moi Avenue'], ['icon' => '⛪', 'text' => 'Tailored for Catholic fathers, canons and cathedral clergy'], ['icon' => '🕯️', 'text' => 'Worn over the cassock as choir dress for solemn celebrations'], ['icon' => '📏', 'text' => 'Cut to your measurements, with guidance on your diocese\'s colour custom'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['canon gown catholic', 'catholic canon robes', 'choir dress kenya', 'canon gown nairobi', 'catholic priest robes kenya', 'cathedral chapter robes', 'padri robes', 'clergy gowns kenya'], 'seo' => ['meta_title' => 'Catholic Canon Gown — Made to Measure, Nairobi', 'meta_description' => 'Canon gowns tailored for Catholic fathers in our Nairobi workshop — made to measure by our own tailors. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'catholic canon gown kenya, canon robes nairobi, catholic priest vestments kenya, choir dress catholic, cathedral canon robes, made to measure clergy gown, church robes kenya', 'og_title' => 'Canon Gown for Catholic Fathers — Tailored in Nairobi', 'og_description' => 'A garment of office for canons and cathedral clergy: made to measure in Nairobi, with guidance on your diocese\'s custom. Delivery across Kenya, East Africa and worldwide.']],
        'ML8FMKZQL' => ['short' => 'A fully bespoke ladies\' clergy dress — designed with you and tailored to your measurements in our Nairobi workshop.', 'description' => '<p>Some callings need a garment no catalogue carries. The <strong>Custom Designed Dress</strong> is Bethany House\'s fully bespoke service for women in ministry — a clergy dress designed around you, then cut by our in-house tailors at Sonalux House, Moi Avenue, Nairobi.</p><ul><li>Choose your silhouette, sleeves, collar style and colour</li><li>Tailored to your exact measurements by our in-house team</li><li>Colours to match your church season, rank or occasion</li><li>Cut and finished in our own Nairobi workshop</li></ul><p>Sit with our tailors in person or share your design and measurements online, and we will bring it to life. Made for women clergy, deaconesses, evangelists and women\'s guild leaders across Kenya and East Africa, with delivery worldwide. Designed with reverence, delivered with care.</p>', 'features' => [['icon' => '✂️', 'text' => 'Fully bespoke — you choose the silhouette, collar, sleeves and colour'], ['icon' => '📏', 'text' => 'Tailored to your exact measurements in our Nairobi workshop'], ['icon' => '🧵', 'text' => 'Cut and finished by our in-house tailors at Sonalux House, Moi Avenue'], ['icon' => '🙏', 'text' => 'For women clergy, deaconesses, evangelists and guild leaders'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['ladies clergy dress', 'custom clergy dress kenya', 'women clergy wear nairobi', 'clergy dress for women', 'bespoke church dress', 'female pastors dress', 'deaconess dress kenya', 'tailored clergy dress'], 'seo' => ['meta_title' => 'Custom Ladies Clergy Dress — Tailored in Nairobi', 'meta_description' => 'Design your own ladies\' clergy dress — bespoke tailoring in our Nairobi workshop. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'custom clergy dress kenya, ladies clergy wear nairobi, women clergy dress, bespoke clergy dress, tailored church dress kenya, deaconess dress, female clergy attire nairobi, made to measure clergy wear', 'og_title' => 'Custom Designed Clergy Dress — Made Just for You', 'og_description' => 'A fully bespoke clergy dress for women in ministry: your design, your measurements, tailored in our Nairobi workshop and delivered across Kenya, East Africa and worldwide.']],
        'ML8FMKZQL-7661' => ['short' => 'Silver-tone bread plate with matching lid — a cool, quiet elegance for serving the communion bread with reverence.', 'description' => '<p>A bread tray in a cool silver-tone finish, supplied as a plate with its matching lid — made to hold the communion bread or wafers as the table is prepared for Holy Communion.</p><p>The lid covers the bread until the moment of distribution, keeping the elements dignified and protected; the open plate then passes through the congregation in orderly reverence. Pair it with a silver-tone cup tray for a quietly matched communion ware set across the whole table.</p><ul><li><strong>Silver-tone finish</strong> with a cool, quiet elegance</li><li><strong>Plate and lid</strong> — the bread stays covered until it is served</li><li>Flat bread-plate form, the companion piece to the cup tray</li><li>Serves Anglican, Catholic, Methodist, PCEA, Pentecostal and independent congregations</li></ul><p>From Sonalux House, Moi Avenue, Nairobi — serving churches across Kenya and East Africa, with worldwide shipping.</p>', 'features' => [['icon' => '🕊️', 'text' => 'Cool silver-tone finish with quiet, dignified elegance'], ['icon' => '🍞', 'text' => 'Holds the communion bread or wafers on a flat serving plate'], ['icon' => '🛡️', 'text' => 'Matching lid covers the bread until the moment of serving'], ['icon' => '🤝', 'text' => 'Pairs beautifully with silver-tone cup trays for a matched set'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['silver bread plate', 'communion bread plate', 'bread plate', 'host plate', 'wafer plate', 'bread tray with lid', 'silver communion plate', 'sinia'], 'seo' => ['meta_title' => 'Silver Bread Tray for Holy Communion — Kenya', 'meta_description' => 'Silver-tone communion bread plate with matching lid. From Sonalux House, Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'silver bread tray, communion bread plate, bread plate kenya, host plate, communion ware nairobi, bread tray with lid, communion trays kenya, church supplies nairobi', 'og_title' => 'Silver Bread Tray — Quiet Elegance for the Lord\'s Table', 'og_description' => 'A cool silver-tone bread plate with matching lid, keeping the communion bread covered until it is served. From Nairobi, delivered worldwide.']],
        'OCJN841JK' => ['short' => 'Hadithi 40 za Biblia zinazopendwa mno, kwa Kiswahili — 40 beloved Bible stories retold for children in the language of home.', 'description' => '<p><strong>Biblia Yangu Kubwa Niipendayo</strong> — "my big Bible that I love" — retells 40 of the most beloved Bible stories in rich, clear Kiswahili, with attractively drawn illustrations that hold a child\'s eye. Children meet Scripture\'s best-loved people in the language of home.</p><ul><li>Hadithi 40 za Biblia zinazopendwa, zikisimuliwa kwa upya kwa Kiswahili</li><li>Attractively drawn, engaging illustrations for the stories</li><li>Mistari ya Maandiko Matakatifu listed with the stories for easy rejea (reference)</li></ul><p>For Swahili-first families, Kiswahili Sunday schools and congregations in Kenya and Tanzania — and diaspora parents who want their children rooted in mother-tongue Scripture.</p><p>Chosen with reverence, delivered with care — from Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📖', 'text' => 'Hadithi 40 za Biblia zinazopendwa — 40 beloved stories retold in Kiswahili'], ['icon' => '🎨', 'text' => 'Attractively drawn, engaging illustrations'], ['icon' => '✝️', 'text' => 'Mistari ya Maandiko listed with the stories for easy reference'], ['icon' => '🏠', 'text' => 'Mother-tongue Scripture for Swahili-first families and Sunday schools'], ['icon' => '🌍', 'text' => 'Loved in Kenya, Tanzania and the Swahili-speaking diaspora']], 'aliases' => ['biblia ya watoto', 'bibilia ya watoto', 'swahili children bible', 'kiswahili bible stories', 'hadithi za biblia', 'swahili bible kenya', 'biblia takatifu watoto', 'tanzania children bible', 'biblia yangu kubwa niipendayo'], 'seo' => ['meta_title' => 'Biblia ya Watoto — Kiswahili Children\'s Bible', 'meta_description' => 'Hadithi 40 za Biblia kwa Kiswahili — 40 beloved stories with attractive illustrations for children. Delivered across Kenya, Tanzania and worldwide.', 'meta_keywords' => 'biblia ya watoto, swahili children bible, kiswahili bible stories kenya, hadithi za biblia, children bible nairobi, swahili sunday school, biblia yangu kubwa niipendayo, tanzania children bible', 'og_title' => 'Biblia Yangu Kubwa Niipendayo — Hadithi 40 za Biblia', 'og_description' => 'My big Bible that I love — 40 beloved Bible stories retold in Kiswahili with attractive illustrations. Delivered from Nairobi across Kenya, East Africa and worldwide.']],
        'OCJN841JK-8CD6' => ['short' => 'Large tallit with a generous drape for leading prayer and worship — Hebrew blessing inscription, Scripture at each corner.', 'description' => '<p>Our large tallit is the full-drape prayer shawl — generous enough to lift over the shoulders and enwrap the whole frame in prayer, adoration and worship. It is the size ministers and intercessors reach for when leading prayer, covering a season of intercession, or praying over others.</p><p>It carries an inscription of the traditional Hebrew blessing — <strong>"Blessed are You, Lord our God, King of the universe, who has sanctified us with His commandments and commanded us to enwrap ourselves in the tzitzit (fringes)"</strong> — so that putting on the tallit is itself an act of prayer.</p><p>Each corner bears a Scripture: Malachi 4:2, 2 Corinthians 5:21, Matthew 14:36 and Isaiah 53:5 — healing, righteousness, touch and atonement at the four corners of your prayer.</p><p>Available in royal blue, navy blue and purple. From Sonalux House, Moi Avenue, Nairobi CBD — delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🙌', 'text' => 'Full, generous drape — enwrap the whole frame in prayer and worship'], ['icon' => '🕎', 'text' => 'Inscribed with the traditional Hebrew blessing for enwrapping in the tzitzit'], ['icon' => '📖', 'text' => 'Corner Scriptures: Malachi 4:2, 2 Cor 5:21, Matthew 14:36, Isaiah 53:5'], ['icon' => '🎨', 'text' => 'In royal blue, navy blue and purple'], ['icon' => '⛪', 'text' => 'Favoured by ministers and intercessors for leading corporate prayer'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['large prayer shawl', 'big tallit', 'tallit large kenya', 'talit', 'tallis', 'intercessors prayer shawl', 'navy prayer shawl', 'prayer shawl for ministers'], 'seo' => ['meta_title' => 'Large Tallit Prayer Shawl in Kenya', 'meta_description' => 'Large full-drape tallit in royal blue, navy or purple with corner Scriptures — for ministers and intercessors. From Nairobi, delivered worldwide.', 'meta_keywords' => 'large tallit kenya, large prayer shawl nairobi, tallit for ministers, intercession prayer shawl, navy blue tallit, buy tallit online kenya, prayer shawl with verses', 'og_title' => 'Large Tallit — Enwrapped for Intercession', 'og_description' => 'The full-drape prayer shawl for leading worship and covering intercession — Hebrew blessing, four corner Scriptures. Delivered from Nairobi.']],
        'OUTOIDPWY' => ['short' => 'Medium tallit in royal blue, navy or purple, with the traditional Hebrew blessing inscription and a Scripture verse at each corner.', 'description' => '<p>Our medium tallit is the prayer shawl for the everyday intercessor — used during prayers, adoration and worship, and sized to wrap comfortably for personal devotion at home, in the prayer room or in the sanctuary.</p><p>Each tallit bears an inscription of the traditional Hebrew blessing: <strong>"Blessed are You, Lord our God, King of the universe, who has sanctified us with His commandments and commanded us to enwrap ourselves in the tzitzit (fringes)."</strong> At its four corners, four Scriptures trace a quiet gospel arc — healing promised, righteousness given, the Healer touched, the atonement finished:</p><ul><li>Malachi 4:2 — healing in His wings</li><li>2 Corinthians 5:21 — made the righteousness of God</li><li>Matthew 14:36 — they touched the fringe of His garment</li><li>Isaiah 53:5 — by His wounds we are healed</li></ul><p>Available in royal blue, navy blue and purple. From Sonalux House, Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📖', 'text' => 'A Scripture at each corner — Malachi 4:2, 2 Cor 5:21, Matthew 14:36, Isaiah 53:5'], ['icon' => '🕎', 'text' => 'Bears the traditional Hebrew blessing for enwrapping in the tzitzit'], ['icon' => '🎨', 'text' => 'In royal blue, navy blue and purple'], ['icon' => '🙏', 'text' => 'Medium size — wraps comfortably for daily personal prayer and intercession'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['prayer shawl medium', 'medium prayer shawl', 'tallit medium kenya', 'talit', 'tallis', 'messianic tallit', 'blue prayer shawl', 'purple prayer shawl'], 'seo' => ['meta_title' => 'Medium Tallit Prayer Shawl — Kenya', 'meta_description' => 'Medium tallit in royal blue, navy or purple — Hebrew blessing inscription, Scripture at every corner. Order from Nairobi; delivery worldwide.', 'meta_keywords' => 'medium tallit kenya, prayer shawl nairobi, royal blue tallit, purple prayer shawl, tallit with scripture corners, messianic tallit kenya, buy prayer shawl online kenya', 'og_title' => 'Medium Tallit — A Gospel at the Four Corners', 'og_description' => 'Royal blue, navy or purple prayer shawl with the Hebrew blessing and four corner Scriptures. From Nairobi, delivered with care.']],
        'RONG11JY7' => ['short' => 'Cincture belt worn at the waist with the cassock and liturgical vestments — girded for service; made to order in our Nairobi workshop.', 'description' => '<p>The cincture belt is worn with Christian liturgical vestments, encircling the body around or above the waist — gathering the cassock and giving the minister a clean, finished silhouette. It carries the same ancient symbolism as the rope cincture: girded, ready, set apart for service.</p><p>Distinct from our tasselled <strong>cincture rope</strong>, this is the cincture worn with the cassock itself — and because our vestments are sewn in-house at our Nairobi workshop, your cincture belt can be <strong>made to order</strong> to complement your cassock.</p><p>A staple for pastors, priests and bishops across Anglican, Catholic, Orthodox and other congregations in Kenya and East Africa. Fitted at Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya and worldwide.</p>', 'features' => [['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop to complement your cassock'], ['icon' => '🧵', 'text' => 'Encircles the body around or above the waist, worn with Christian liturgical vestments'], ['icon' => '🕊️', 'text' => 'Carries the girding symbolism of readiness and consecrated service'], ['icon' => '⛪', 'text' => 'Worn by pastors, priests and bishops across Anglican, Catholic, Orthodox and other traditions'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['cincture belt', 'cassock belt', 'clergy belt', 'sincture belt', 'cassock waistband', 'cincture belt kenya'], 'seo' => ['meta_title' => 'Cassock Cincture Belts — Tailored in Nairobi', 'meta_description' => 'Cincture belt for cassocks and liturgical vestments, made to order in our Nairobi workshop. Delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'cincture belt kenya, cassock belt nairobi, clergy belt kenya, made to measure vestments nairobi, clergy wear moi avenue, church supplies nairobi cbd', 'og_title' => 'The Cincture Belt — A Tailored Finish for the Cassock', 'og_description' => 'Cincture belt worn with the cassock and liturgical vestments, made to order in our Nairobi workshop. Delivered with care across Kenya and worldwide.']],
        'RONG11JY7-7176' => ['short' => 'A horn-shaped vessel for anointing oil, after Samuel\'s horn that anointed David — a vessel of consecration and a teaching sign.', 'description' => '<p>"Fill your horn with oil and be on your way" (1 Samuel 16:1). With a horn of oil Samuel anointed David among his brothers, and with a horn of oil Zadok the priest anointed Solomon king (1 Kings 1:39). The anointing horn recalls that vessel — and in Hebrew idiom the horn itself speaks of strength.</p><p>Shaped after the biblical horn of oil, it serves both as a working vessel for carrying and pouring anointing oil and as a vivid teaching object for sermons on calling, kingship and consecration.</p><p>For pastors, bishops and ministry leaders across every tradition — for anointing services, ordinations, commissionings and the blessing of homes. Pair it with anointing oil from our range and the vessel is ready for the moment of prayer.</p><p>From Bethany House, Sonalux House, Moi Avenue, Nairobi — delivered across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '👑', 'text' => 'Recalls Samuel\'s horn of oil that anointed David — and Zadok\'s that anointed Solomon'], ['icon' => '🏺', 'text' => 'A working vessel for carrying and pouring anointing oil'], ['icon' => '📖', 'text' => 'A vivid teaching object for sermons on calling, kingship and consecration'], ['icon' => '🙏', 'text' => 'For anointing services, ordinations, commissionings and blessings of homes'], ['icon' => '⛪', 'text' => 'At home in every tradition, from cathedral to house fellowship'], ['icon' => '🚚', 'text' => 'From Bethany House, Nairobi — delivered across Kenya, East Africa and worldwide']], 'aliases' => ['oil horn', 'anointing oil horn', 'horn of oil', 'pembe ya mafuta', 'samuel anointing horn', 'biblical anointing horn', 'horn of anointing oil'], 'seo' => ['meta_title' => 'Anointing Horn in Nairobi, Kenya', 'meta_description' => 'The biblical horn of oil — a vessel for anointing and a teaching sign, after 1 Samuel 16. From Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'anointing horn kenya, horn of oil, anointing oil horn nairobi, biblical anointing horn, anointing vessel, church supplies nairobi, mafuta ya upako, anointing service supplies', 'og_title' => 'Anointing Horn — The Biblical Horn of Oil', 'og_description' => 'A horn-shaped vessel for anointing oil, after the horn with which Samuel anointed David. A vessel of consecration and a teaching sign — from Bethany House, Nairobi.']],
        'SF-CHL-01' => ['short' => 'Chalice and paten in one radiant gold-tone set — the vessels of Holy Communion, matched and ready for the altar together.', 'description' => '<p>The chalice and its paten belong together — the cup of Holy Communion and the shallow plate that traditionally rests upon it, bearing the bread. This gold-tone set arrives as a matched pair, the way sacristans and celebrants have always preferred to furnish the altar.</p><p>The radiant golden finish lends festal dignity to the Eucharist, while the classic form — cup, stem and foot — serves the celebrant faithfully through every service. Fitting for Catholic Mass, Anglican (ACK) Holy Communion and the Lord\'s Supper in Methodist, PCEA, Pentecostal and independent churches alike.</p><ul><li>Matched <strong>chalice and paten set</strong> — ready for the altar together</li><li>Radiant gold-tone finish for festal dignity</li><li>Classic chalice form: cup, stem and foot</li><li>Care: hand-wash gently and dry with a soft cloth; never use abrasives on the finish</li></ul><p>A treasured gift for ordinations, ministry anniversaries and the furnishing of a new sanctuary — delivered from Sonalux House, Moi Avenue, Nairobi, across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✨', 'text' => 'Matched chalice and paten — the vessels of Holy Communion, ready for the altar as a pair'], ['icon' => '🌟', 'text' => 'Radiant gold-tone finish lends festal dignity to the Eucharist'], ['icon' => '✋', 'text' => 'Classic form: cup, stem and foot — balanced in the celebrant\'s hand'], ['icon' => '🎁', 'text' => 'A treasured gift for ordinations, ministry anniversaries and new sanctuaries'], ['icon' => '🧼', 'text' => 'Hand-wash gently and dry with a soft cloth — never abrasives on the finish'], ['icon' => '🚚', 'text' => 'Delivered from Moi Avenue, Nairobi, across Kenya, East Africa and worldwide']], 'aliases' => ['chalice and paten', 'chalice set with paten', 'communion chalice set', 'gold chalice kenya', 'ordination gift chalice', 'paten set', 'holy communion set'], 'seo' => ['meta_title' => 'Golden Chalice with Paten Set — Kenya', 'meta_description' => 'Matched gold-tone chalice and paten set for Holy Communion. From Nairobi CBD, delivered across Kenya, East Africa and worldwide. Order for your altar today.', 'meta_keywords' => 'chalice set with paten, golden chalice kenya, chalice and paten nairobi, communion chalice set, holy communion set kenya, ordination gift kenya, communion ware nairobi', 'og_title' => 'Golden Chalice Cup with Paten Set — Ready for the Altar Together', 'og_description' => 'The cup and the plate of Holy Communion as a matched gold-tone pair — a festal set for the altar and a treasured ordination gift. From Bethany House, Nairobi, delivered worldwide.']],
        'SF-CHS-01' => ['short' => 'A richly embroidered chasuble for the celebrant at the Eucharist — made to order in Nairobi in your liturgical colour.', 'description' => '<p>The chasuble is the outermost vestment of the celebrant — the flowing, poncho-like garment worn over alb and stole at the Mass or Eucharist in Catholic, Anglican and Methodist use. When the celebrant stands at the altar, this is the garment the congregation sees.</p><p>Our ornate chasuble is finished with rich embroidered ornament — careful handwork worthy of the altar. Each one is made to order at our Nairobi workshop in the liturgical colour your season calls for.</p><p>It serves parish priests, cathedral celebrants and visiting clergy across Kenya and East Africa — for Sunday Eucharist, festal seasons, ordinations and the great feasts of the church year.</p>', 'features' => [['icon' => '✨', 'text' => 'Richly embroidered ornament worthy of the Eucharist'], ['icon' => '🎨', 'text' => 'Made in the liturgical colours of the church year'], ['icon' => '✂️', 'text' => 'Made to order at our Nairobi workshop'], ['icon' => '⛪', 'text' => 'For Catholic, Anglican and Methodist celebrants'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['embroidered chasuble', 'chasuble kenya', 'catholic chasuble', 'priest chasuble nairobi', 'mass vestments kenya', 'chasable', 'chasible', 'eucharistic vestments'], 'seo' => ['meta_title' => 'Embroidered Chasuble in Nairobi, Kenya', 'meta_description' => 'Ornate embroidered chasuble made to order in Nairobi in your liturgical colour. Vesting celebrants across Kenya and East Africa. Order today.', 'meta_keywords' => 'chasuble kenya, embroidered chasuble nairobi, catholic chasuble kenya, priest vestments nairobi, mass vestments kenya, anglican chasuble, church vestments nairobi', 'og_title' => 'Ornate Embroidered Chasuble — Made to Order', 'og_description' => 'The garment the congregation sees at the altar — richly embroidered and made to order in Nairobi. Chosen with reverence, delivered with care.']],
        'SF-CSK-01' => ['short' => 'Complete five-piece ladies\' cassock set — cassock, shirt, collar, stole and cincture belt — ordination-ready in one order.', 'description' => '<p>Rooted in rich church tradition, the cassock is the garment that immediately identifies the clergy — a daily reminder of faithful service and the ideal base for every worship setting. The Classic Princes Cassock Set brings that tradition to lady ministers in a graceful princess-cut silhouette.</p><p>This is a complete, <strong>ordination-ready outfit in a single order</strong>. The set includes:</p><ul><li>1 princess-cut cassock</li><li>1 shirt</li><li>1 collar</li><li>1 stole — the badge of ordained ministry</li><li>1 cincture belt</li></ul><p>Tailored with care in our Nairobi workshop and delivered across Kenya, East Africa and worldwide, it serves women clergy, deaconesses and lady ministers preparing for ordination, installation or faithful weekly ministry.</p>', 'features' => [['icon' => '📦', 'text' => 'Five pieces in one order: cassock, shirt, collar, stole and cincture belt'], ['icon' => '👗', 'text' => 'Classic princess-cut ladies\' cassock — fitted, graceful and reverent'], ['icon' => '🕊️', 'text' => 'Ordination-ready — everything a lady minister needs to be robed'], ['icon' => '✂️', 'text' => 'Tailored with care in our Nairobi workshop'], ['icon' => '🌍', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['ladies cassock set', 'princess cassock set', 'women cassock set', 'ordination set for women', 'cassock full set', 'lady minister robes', 'cassock and stole set', 'clergy set for ladies'], 'seo' => ['meta_title' => 'Ladies Cassock Set — 5-Piece, Tailored in Nairobi', 'meta_description' => 'Five-piece ladies cassock set — cassock, shirt, collar, stole and cincture belt. Tailored in Nairobi, delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'ladies cassock set, princess cassock set kenya, women clergy vestments, ordination set kenya, cassock and stole set, clergy attire nairobi, lady minister robes, church robes kenya', 'og_title' => 'Classic Princes Cassock Set — Ordination-Ready in One Order', 'og_description' => 'Cassock, shirt, collar, stole and cincture belt — the complete wardrobe for a lady minister, tailored in Nairobi. Chosen with reverence, delivered with care.']],
        'SF-DEV-01' => ['short' => '365 Days With Jesus — a daily devotional companion for a year of walking with Christ, one day at a time.', 'description' => '<p><strong>365 Days With Jesus</strong> is a daily devotional with a reading for every day of the year — a simple companion that turns good intentions into a daily rhythm of walking with Christ.</p><p>Devotionals endure because they make time with God a habit. Whether you are establishing your first quiet time or renewing a well-worn one, a devotional that asks only a few minutes a day gives back a whole year of drawing nearer to Jesus.</p><ul><li>365 daily devotional readings — one for every day of the year</li><li>Start any day of the year, not just 1 January</li><li>A gentle daily rhythm that builds a lasting quiet time</li></ul><p>A thoughtful gift for <strong>New Year, confirmation, women\'s and men\'s fellowships and staff appreciation</strong> — it pairs beautifully with a Bible as a care package. Chosen with reverence, delivered with care — from Nairobi across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '📅', 'text' => '365 daily readings — one for every day of the year'], ['icon' => '🙏', 'text' => 'Builds a lasting daily quiet time with Jesus'], ['icon' => '🎁', 'text' => 'Loved for New Year, confirmation and fellowship gifting'], ['icon' => '🤝', 'text' => 'Ideal staff-appreciation and discipleship-group gift']], 'aliases' => ['daily devotional book', '365 devotional', 'one year devotional', 'devotional kenya', 'morning devotion book', 'christian devotional nairobi', 'new year devotional gift', '365 days with jesus'], 'seo' => ['meta_title' => '365 Days With Jesus — Daily Devotional, Kenya', 'meta_description' => '365 Days With Jesus — a devotional reading for every day of a year of walking with Christ. A loved gift. Delivered across Kenya and worldwide.', 'meta_keywords' => 'daily devotional kenya, 365 devotional, devotional book nairobi, one year devotional, christian gift kenya, new year devotional, confirmation gift, fellowship gift book', 'og_title' => '365 Days With Jesus — A Year of Walking with Christ', 'og_description' => 'A devotional reading for every day of the year — the daily companion that turns intention into rhythm. Delivered from Nairobi across Kenya and worldwide.']],
        'SF-HST-01' => ['short' => 'Unleavened altar breads for the Eucharist — 1,000 hosts per pack, ready for the ciborium and the faithful at the rail.', 'description' => '<p>Communion hosts — also called altar breads — are the small unleavened breads specially prepared for the celebration of Holy Communion and the Eucharist. Placed in the ciborium and borne to the faithful, the host stands at the heart of the church\'s worship: the bread of the Lord\'s Table, a sign of His body, of unity, of spiritual nourishment and of sharing in Christ\'s sacrifice.</p><p>This pack supplies <strong>1,000 hosts</strong> — ample provision for parishes with several Sunday celebrations, sodality days and seasons of high attendance.</p><p>Suited to Catholic parishes and to Anglican and other congregations that prefer the traditional host — received as your tradition directs. Store airtight in a cool, dry place and handle with dry hands.</p><p>From Bethany House, Sonalux House, Moi Avenue, Nairobi — delivered to parishes across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✝️', 'text' => 'Unleavened altar breads prepared for the celebration of the Eucharist'], ['icon' => '📦', 'text' => '1,000 hosts per pack — ample for parishes with several celebrations'], ['icon' => '⛪', 'text' => 'Ready for the ciborium and reverent distribution to the faithful'], ['icon' => '🙏', 'text' => 'A sign of the Lord\'s body, of unity and of spiritual nourishment'], ['icon' => '🫙', 'text' => 'Store airtight in a cool, dry place; handle with dry hands'], ['icon' => '🚚', 'text' => 'Delivery to parishes across Kenya, East Africa and worldwide']], 'aliases' => ['altar bread', 'hosts for mass', 'eucharist bread', 'altar breads 1000', 'mkate wa ushirika', 'ekaristi takatifu', 'communion wafers', 'host bread', 'sacramental bread'], 'seo' => ['meta_title' => 'Communion Hosts — 1,000 Pieces, Nairobi', 'meta_description' => 'Unleavened altar breads for the Eucharist — 1,000 hosts per pack. Order for your parish from Bethany House, Nairobi; delivery across Kenya and beyond.', 'meta_keywords' => 'communion hosts kenya, altar bread nairobi, hosts for mass kenya, eucharist bread, altar bread suppliers kenya, catholic church supplies nairobi, communion elements kenya, ekaristi takatifu', 'og_title' => 'Communion Hosts — 1,000 Altar Breads for the Eucharist', 'og_description' => 'Unleavened altar breads for Holy Communion — 1,000 hosts per pack, ready for the ciborium and the faithful. From Bethany House, Nairobi, chosen with reverence.']],
        'SF-PCX-01' => ['short' => 'Bishop\'s pectoral cross in a bright gold finish — the historic insignia of the shepherd\'s office, resting at the sternum.', 'description' => '<p>Since the late Middle Ages the pectoral cross has been the mark of bishops — and today of popes, cardinals, abbots and senior clergy across the traditions. Worn over the breastbone, it places the cross of Christ visibly over the heart of the shepherd.</p><p>This piece carries a gleaming <strong>gold finish</strong> in the classic convention, catching the light as the wearer processes, presides and blesses. It sits naturally over a cassock, robe or suit, resting at the sternum.</p><p>For bishops and senior clergy — including apostles and overseers in Kenya’s Pentecostal and independent churches — and a fitting gift for a consecration or enthronement. Available from our Sonalux House showroom on Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '✨', 'text' => 'Gleaming gold finish in the classic episcopal convention'], ['icon' => '⛪', 'text' => 'Historic insignia of bishops and senior clergy since the late Middle Ages'], ['icon' => '🙏', 'text' => 'Rests at the sternum over cassock, robe or suit'], ['icon' => '🎁', 'text' => 'A fitting consecration or enthronement gift'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['pectoral cross', 'gold pectoral cross', 'bishop cross', 'episcopal cross', 'golden cross for bishops', 'msalaba wa askofu', 'clergy cross nairobi', 'bishop regalia kenya'], 'seo' => ['meta_title' => 'Gold-Finish Pectoral Cross — Bishop\'s Insignia, Nairobi', 'meta_description' => 'A gold-finish pectoral cross for bishops and senior clergy — the historic insignia of the shepherd\'s office. From Nairobi, delivered worldwide. Order today.', 'meta_keywords' => 'gold finish pectoral cross, pectoral cross nairobi, bishop cross kenya, episcopal cross, bishop regalia kenya, clergy wear moi avenue, church supplies nairobi cbd, consecration gift kenya', 'og_title' => 'Gold Finish Pectoral Cross — The Bishop\'s Insignia', 'og_description' => 'Worn over the breastbone since the late Middle Ages — a gleaming gold-finish pectoral cross for bishops and senior clergy. From Bethany House, Nairobi.']],
        'SF-SHT-01' => ['short' => 'Clergy shirt with the full round collar — the white band showing all round for a clean, classic ministerial look.', 'description' => '<p>The <strong>Round Collar Clergy Shirt</strong> carries the most recognisable mark of ministry: the full round collar, with the white band encircling the neck and showing all the way round. Often called the "dog collar," it gives a minister a clean, classic look — beautiful at the pulpit, unmistakable in the community.</p><p>Tailored in our Nairobi workshop at Sonalux House, Moi Avenue, each shirt is made to order, so it is cut to your fit rather than off the rack. Wear it on its own for daily ministry, or under a cassock, gown or suit for services and occasions.</p><p>A wardrobe staple for pastors, reverends, priests and bishops across Kenya and East Africa — order several and be ready for every week of ministry. Delivery available worldwide.</p>', 'features' => [['icon' => '⚪', 'text' => 'Full round collar — the white band shows all the way round'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop, cut to your fit'], ['icon' => '👔', 'text' => 'Wears well alone or under a cassock, gown or suit'], ['icon' => '🙏', 'text' => 'A staple for pastors, reverends, priests and bishops'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['clergy shirts kenya', 'round collar shirt nairobi', 'dog collar shirt', 'reverend collar shirt', 'full collar clergy shirt', 'pastors shirt kenya', 'neckband clergy shirt', 'clergy wear nairobi', 'clergy shirts in kenya'], 'seo' => ['meta_title' => 'Round Collar Clergy Shirts in Nairobi, Kenya', 'meta_description' => 'Classic full round collar clergy shirts, made to order in Nairobi. Shop clergy wear delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'clergy shirts kenya, round collar shirt nairobi, dog collar shirt kenya, reverend collar shirt, clergy shirts in kenya, clergy wear nairobi, pastors shirts kenya, neckband shirt clergy', 'og_title' => 'Round Collar Clergy Shirt — The Classic Mark of Ministry', 'og_description' => 'The full round collar, tailored in Nairobi to your fit. A clergy-wardrobe staple, delivered across Kenya, East Africa and worldwide.']],
        'SF-STL-01' => ['short' => 'Fully reversible stoles finished on both faces in two liturgical colours — one finely made stole, twice the wardrobe.', 'description' => '<p>A double-sided stole is finished with equal care on both faces, each in its own liturgical colour — a genuinely practical vestment for working clergy, carrying one stole across two seasons of the church year.</p><p>Our double-sided stoles are tailored in-house at our Nairobi workshop, with clean reversible construction so either face sits beautifully at the altar. Choose the colour pairing your calendar calls for — <strong>purple with white</strong> traditionally carries a minister from Advent and Lent straight into Christmas and Easter.</p><p>They dress priests, pastors, reverends and deacons across Anglican, Catholic, Methodist, PCEA and Pentecostal congregations in Kenya and East Africa — and pair naturally with a cassock, alb or preaching gown from our vestment workshop.</p>', 'features' => [['icon' => '🔄', 'text' => 'Reversible — two liturgical colours finished into one stole'], ['icon' => '📅', 'text' => 'Carries you across two seasons of the church year in a single piece'], ['icon' => '✂️', 'text' => 'Clean two-faced construction, tailored in-house in Nairobi'], ['icon' => '🎨', 'text' => 'Colour pairings chosen to match your tradition\'s calendar'], ['icon' => '⛪', 'text' => 'For Anglican, Catholic, Methodist, PCEA and Pentecostal clergy'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['reversible stole', 'two sided stole', 'double side stole', 'reversible clergy stole', 'two colour stole', 'priest stole kenya', 'stole nairobi', 'clergy stoles kenya'], 'seo' => ['meta_title' => 'Double-Sided Stoles in Nairobi, Kenya', 'meta_description' => 'Reversible clergy stoles finished in two liturgical colours — one stole for two seasons. Tailored in Nairobi, delivered across Kenya and East Africa.', 'meta_keywords' => 'double sided stole kenya, reversible stole nairobi, two colour clergy stole, clergy stoles kenya, priest stole price in kenya, liturgical stole nairobi, vestments kenya', 'og_title' => 'Double-Sided Stoles — Two Seasons, One Beautiful Stole', 'og_description' => 'Finished on both faces in two liturgical colours, our reversible stoles serve your ministry across the church year. Tailored in Nairobi, delivered with care.']],
        'SF-TLT-01' => ['short' => 'Classic tallit prayer shawl for wrapping yourself in prayer, adoration and worship — the prayer heritage of the Scriptures.', 'description' => '<p>The tallit is the prayer shawl of the Scriptures — the garment whose corner fringes (tzitzit) were commanded in Numbers 15:38–40 as a knotted reminder of God\'s commands. To put it on is to be wrapped in the Word before a word of prayer is spoken.</p><p>For Christian believers the tallit carries a tender echo: in Hebrew, kanaf means both "corner" and "wing," so Malachi\'s promise that the Sun of Righteousness will arise "with healing in His wings" is read onto its corners — and it was the fringe of Jesus\' garment that the ailing woman reached out to touch, and was healed (Matthew 9:20).</p><p>Welcoming to Messianic and mainstream Christian worshippers alike, the tallit is loved in Kenya for personal devotion, intercession, adoration and corporate worship. Available at Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🕊️', 'text' => 'Wrap yourself in prayer — the tallit tradition of Numbers 15:38–40'], ['icon' => '🪢', 'text' => 'Corner fringes (tzitzit) — a knotted reminder of God\'s commands'], ['icon' => '🙌', 'text' => 'Healing in His wings — Malachi 4:2 read onto the tallit\'s corners'], ['icon' => '🙏', 'text' => 'For personal devotion, intercession, adoration and corporate worship'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['prayer shawl', 'jewish prayer shawl', 'messianic prayer shawl', 'talit', 'tallis', 'prayer shawl kenya', 'tzitzit shawl', 'prayer mantle'], 'seo' => ['meta_title' => 'Tallit Prayer Shawls in Nairobi, Kenya', 'meta_description' => 'Classic tallit prayer shawl — the prayer heritage of the Scriptures, welcoming to all believers. From Sonalux House, Nairobi; worldwide delivery.', 'meta_keywords' => 'tallit kenya, prayer shawl nairobi, messianic prayer shawl, tzitzit fringes, buy tallit online kenya, prayer mantle kenya, church supplies nairobi cbd', 'og_title' => 'The Tallit — Wrapped in the Word Before You Pray', 'og_description' => 'The prayer shawl of the Scriptures, its fringes a reminder of God\'s commands. Chosen with reverence in Nairobi, delivered worldwide.']],
        'UE81UOJY5' => ['short' => 'Made-to-measure ordination gown tailored in Nairobi — a dignified robe for the day your calling is confirmed.', 'description' => '<p>An ordination is a once-in-a-lifetime milestone — the day a calling is publicly confirmed before God and the church. The Bethany House <strong>Ordination Gown</strong> is tailored for that day: a dignified, full-length robe that lets a candidate stand at the altar with reverence and confidence.</p><p>Each gown is made to measure in our Nairobi workshop at Sonalux House, Moi Avenue. Share your measurements and preferred detailing and our tailors will cut the gown to fit you — and to serve you through years of ministry beyond the ordination itself.</p><p>Suited to candidates and churches across Kenya and East Africa — Anglican/ACK, Methodist, PCEA, Pentecostal and independent congregations alike — with delivery available worldwide. Chosen with reverence, delivered with care.</p>', 'features' => [['icon' => '✂️', 'text' => 'Made to measure in our Nairobi workshop at Sonalux House, Moi Avenue'], ['icon' => '🕊️', 'text' => 'Tailored for ordinations, consecrations and installations'], ['icon' => '📏', 'text' => 'Cut to your measurements for a dignified fit at the altar'], ['icon' => '⛪', 'text' => 'Serves Anglican/ACK, Methodist, PCEA, Pentecostal and independent churches'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['ordination gown kenya', 'ordination robe', 'ordination gown nairobi', 'clergy gown', 'pastors gown', 'consecration gown', 'church robes kenya', 'joho', 'minister ordination robe'], 'seo' => ['meta_title' => 'Ordination Gown — Tailored in Nairobi, Kenya', 'meta_description' => 'Made-to-measure ordination gowns tailored in Nairobi. Delivery across Kenya, East Africa and worldwide. Order ahead of your ordination day.', 'meta_keywords' => 'ordination gown kenya, ordination gown nairobi, ordination robe, clergy gown kenya, pastors gown nairobi, made to measure ordination gown, church robes kenya, consecration gown kenya', 'og_title' => 'Ordination Gown — For the Day Your Calling Is Confirmed', 'og_description' => 'A dignified, made-to-measure ordination gown tailored in Nairobi. Chosen with reverence, delivered with care — across Kenya, East Africa and worldwide.']],
        'VES-CCS-00101' => ['short' => 'A bishop\'s ceremonial cope supplied as a complete coordinated set — made to order in Nairobi for ordinations and solemn rites.', 'description' => '<p>The cope is the great ceremonial cape of the church — long, open at the front, fastened across the chest by a band, and often finished with a shield-shaped hood at the back. It is the vesture of solemn occasion: processions, ordinations, weddings, funerals and Benediction.</p><p>This Cope Complete Set robes a bishop as one coordinated whole, with the cope and its matching pieces supplied together so nothing is left to chance on the day itself. Each set is made to order at our Nairobi workshop in the colour your rite and season call for.</p><p>Created for bishops and senior clergy across Kenya and East Africa — for ordinations, consecrations, installations and the solemn services where the church puts on her fullest dignity.</p>', 'features' => [['icon' => '👑', 'text' => 'A complete coordinated set — the bishop robed as one whole'], ['icon' => '⛪', 'text' => 'Made for ordinations, consecrations, processions and solemn rites'], ['icon' => '✂️', 'text' => 'Made to order at our Nairobi workshop'], ['icon' => '🎨', 'text' => 'Made in the colour your rite and season call for'], ['icon' => '🕊️', 'text' => 'Classic cope form — open-fronted ceremonial cape, fastened at the chest'], ['icon' => '🚚', 'text' => 'Delivered across Kenya, East Africa and worldwide']], 'aliases' => ['bishop cope', 'cope set', 'bishop regalia kenya', 'ceremonial cope', 'ordination vestments kenya', 'bishops cape', 'cope vestment', 'mavazi ya askofu'], 'seo' => ['meta_title' => 'Bishop\'s Cope Complete Set — Nairobi, Kenya', 'meta_description' => 'Complete cope set for bishops — made to order in Nairobi for ordinations and solemn rites. Delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'bishop cope kenya, cope complete set, bishop regalia kenya, ordination vestments nairobi, ceremonial cope, bishops vestments kenya, consecration robes, clergy vestments nairobi', 'og_title' => 'Cope Complete Set — Robed for the Solemn Day', 'og_description' => 'For ordinations, consecrations and processions: a bishop\'s cope supplied as one coordinated set, made to order in Nairobi. Chosen with reverence, delivered with care.']],
        'VES-K-001' => ['short' => 'Ladies\' head covering for prayer and worship in the 1 Corinthians 11 tradition — crowned for worship with quiet dignity.', 'description' => '<p>Kitambaa — Swahili for cloth — is the ladies\' head covering worn for prayer and worship in the tradition of 1 Corinthians 11: a sign of religious modesty, submission to God and respect for sacred worship, and a living practice across Kenya\'s congregations, from women\'s guilds to Catholic and Orthodox custom.</p><p>Tied gracefully over the hair, the kitambaa marks the wearer as prepared for sacred worship — crowned for worship, carrying herself with dignity into prayer, Holy Communion and church ceremony.</p><p>A graceful choice for women\'s fellowships, guild Sundays, ordinations and everyday services alike — and a thoughtful gift for mothers in the faith. Available at Sonalux House, Moi Avenue, Nairobi CBD, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '👑', 'text' => 'Crowned for worship — the 1 Corinthians 11 tradition of covering in prayer'], ['icon' => '🕊️', 'text' => 'A sign of religious modesty, submission to God and respect for sacred worship'], ['icon' => '🇰🇪', 'text' => 'A living practice in Kenyan congregations — guilds, parishes and fellowships'], ['icon' => '🎁', 'text' => 'A thoughtful gift for mothers in the faith and women\'s fellowships'], ['icon' => '🚚', 'text' => 'Delivered from Nairobi CBD across Kenya, East Africa and worldwide']], 'aliases' => ['head covering', 'ladies head covering', 'church head scarf', 'prayer scarf', 'head wrap for church', 'kitambaa cha kichwa', 'chapel veil', 'women\'s head covering kenya'], 'seo' => ['meta_title' => 'Kitambaa — Ladies\' Head Coverings, Nairobi', 'meta_description' => 'Kitambaa head coverings for prayer and worship in the 1 Corinthians 11 tradition. From Sonalux House, Nairobi — delivery across Kenya and worldwide.', 'meta_keywords' => 'kitambaa kenya, ladies head covering nairobi, church head scarf, prayer head covering, women\'s guild head cloth, chapel veil kenya, church supplies nairobi cbd', 'og_title' => 'Kitambaa — Crowned for Worship', 'og_description' => 'The ladies\' head covering for prayer and worship — reverence, dignity and grace in the 1 Corinthians 11 tradition. Delivered from Nairobi.']],
        'VES-PC-001' => ['short' => 'Our signature made-to-measure cassock — breathable premium fabrics in every liturgical colour, custom-tailored in Nairobi.', 'description' => '<p>This is the cassock as it should be made: <strong>custom-tailored</strong> in our workshop at Sonalux House, Moi Avenue, Nairobi, from breathable, high-quality fabrics that keep you comfortable through the longest services. It is the ankle-length daily garment of the clergy — also called a soutane — worn on its own or as the foundation beneath stole, surplice and chasuble.</p><p>Choose from <strong>all liturgical colours</strong>: black, white, red, purple, blue, green, golden, silver, purple-red and self-print materials (tone-on-tone patterned fabrics). Colour traditionally follows rank and season — black for priests and pastors, purple for bishops, and the church year\'s own colours for its holy seasons.</p><p>Made to measure for pastors, priests and bishops, and available as a standalone garment or a complete vestment set. Visit us at Sonalux House on Moi Avenue or order online with secure worldwide shipping.</p>', 'features' => [['icon' => '✂️', 'text' => 'Custom-tailored at Sonalux House, Moi Avenue, Nairobi — made to measure for you'], ['icon' => '🎨', 'text' => 'All liturgical colours: black, white, red, purple, blue, green, golden, silver, purple-red, self print'], ['icon' => '🌬️', 'text' => 'Breathable, high-quality fabrics for comfort through long services'], ['icon' => '👑', 'text' => 'Colours to match rank — black for priests and pastors, purple for bishops'], ['icon' => '📦', 'text' => 'Order as a standalone garment or a complete vestment set'], ['icon' => '🌍', 'text' => 'Secure worldwide shipping from Nairobi']], 'aliases' => ['soutane', 'clergy robe', 'cassock price in kenya', 'made to measure cassock', 'cassocks tailored nairobi', 'bishop cassock purple', 'black cassock', 'kanzu', 'cassok', 'casock', 'church robe kenya', 'clergy wear nairobi'], 'seo' => ['meta_title' => 'Cassock — Custom-Tailored in Nairobi, Kenya', 'meta_description' => 'Premium cassocks custom-tailored at Sonalux House, Moi Avenue, Nairobi. All liturgical colours, breathable fabrics, secure worldwide shipping.', 'meta_keywords' => 'cassock price in kenya, cassocks tailored nairobi, made to measure cassock, clergy cassock kenya, bishop cassock purple, soutane, clergy attire moi avenue, church robes kenya, vestments nairobi', 'og_title' => 'The Bethany House Cassock — Every Colour, Made to Measure', 'og_description' => 'Custom-tailored on Moi Avenue in breathable premium fabrics, in every liturgical colour from black to bishop\'s purple to self print. Chosen with reverence, delivered with care — worldwide.']],
        'VES-SR-001' => ['short' => 'The bishop\'s crozier — a shepherd\'s-crook pastoral staff symbolising Christ-like care for the flock of God.', 'description' => '<p>The <strong>crozier</strong> — also spelt crosier, and formally the <strong>pastoral staff</strong> — is the shepherd’s-crook staff carried by bishops and certain abbots during liturgical celebrations. Documented as episcopal insignia since the Fourth Council of Toledo in 633, it symbolises the bishop’s role as shepherd of God’s people, after the example of Christ, the Good Shepherd (John 10).</p><p>Its very shape preaches: the curve to draw back the straying, the tip to steady the flock — echoing the ordination charge, keep watch over the whole flock.</p><p>Carried in processions, ordinations, confirmations and every solemn celebration, it serves Anglican, Catholic, Methodist, Orthodox and Pentecostal episcopates alike. Available at Sonalux House, Moi Avenue, Nairobi, with delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🐑', 'text' => 'The shepherd\'s-crook staff of bishops and certain abbots'], ['icon' => '📜', 'text' => 'Documented episcopal insignia since the Fourth Council of Toledo (633)'], ['icon' => '✝️', 'text' => 'Recalls Christ the Good Shepherd — the curve draws back the straying'], ['icon' => '⛪', 'text' => 'Carried in processions, ordinations and solemn celebrations'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['crosier', 'crozier', 'pastoral staff', 'shepherd staff', 'shepherds rod', 'bishop staff', 'bishop\'s staff kenya', 'fimbo ya askofu', 'shepherd\'s crook'], 'seo' => ['meta_title' => 'Bishop\'s Crozier / Pastoral Staff — Nairobi, Kenya', 'meta_description' => 'The bishop\'s crozier — shepherd\'s-crook pastoral staff for processions and ordinations. From Nairobi CBD, delivered across Kenya, East Africa and worldwide.', 'meta_keywords' => 'bishop crozier kenya, crosier nairobi, pastoral staff kenya, shepherd staff, bishop staff nairobi, bishop regalia kenya, fimbo ya askofu, church supplies nairobi cbd', 'og_title' => 'The Bishop\'s Crozier — The Shepherd\'s Staff', 'og_description' => 'A shepherd\'s-crook pastoral staff after the example of Christ the Good Shepherd — carried at processions and ordinations. From Bethany House, Nairobi, delivered worldwide.']],
        'XYULGK29K-5D98' => ['short' => 'Gold-plated communion cup tray holding 40 cups — stackable, dignified, and made to scale with your congregation.', 'description' => '<p>A gold-plated communion tray that seats <strong>40 individual cups</strong> — the working heart of communion ware for congregations that serve with individual cups. Each cup sits upright and secure as servers move along the rows.</p><p>The trays are stackable, so several travel and store as one — a single tray for a small fellowship, a stack for the full assembly. An engraved personalisation option lets your church add its own mark to the set.</p><ul><li><strong>Holds 40 cups</strong> for individual-cup communion service</li><li><strong>Gold-plated finish</strong> that brings warmth and dignity to the table</li><li><strong>Stackable</strong> — scale the set as your congregation grows</li><li><strong>Unbreakable options</strong> available for lasting use</li><li>Engraved personalisation available for your congregation</li></ul><p>Serving Methodist, PCEA, Pentecostal, Anglican, Catholic and independent churches from Sonalux House, Moi Avenue, Nairobi — with wholesale options for bulk church orders, and delivery across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🍷', 'text' => 'Seats 40 individual communion cups, each upright and secure'], ['icon' => '✨', 'text' => 'Gold-plated finish that brings warmth and dignity to the table'], ['icon' => '🗼', 'text' => 'Stackable — carry and store several trays as one as you grow'], ['icon' => '✍️', 'text' => 'Engraved personalisation available for your congregation'], ['icon' => '⛪', 'text' => 'Scales from a small fellowship to the full assembly'], ['icon' => '🚚', 'text' => 'Delivery from Nairobi across Kenya, East Africa and worldwide']], 'aliases' => ['communion cup tray', 'golden cup tray', '40 cup communion tray', 'gold plated communion tray', 'communion trays kenya', 'stackable communion tray', 'communion wares', 'gold communion t