        'XZIQU3RFM-8032' => ['short' => 'The New King James Version in generous giant print — the majesty of the KJV, in the English you speak, easy on every eye.', 'description' => '<p>The <strong>NKJV Giant Print Bible</strong> brings together two mercies in one volume: the New King James Version, which uses clear modern English while preserving the beloved style and cadence of the King James, and generous giant print that makes every word prominent on the page.</p><p>It is the bridge Bible for readers raised on the KJV — those who love the majesty of the old language but want to understand every verse.</p><ul><li>Giant print — word visibility that is kind to seniors, low-vision readers and dim-lit services</li><li>Clear modern English that preserves the King James style</li><li>Reads beautifully aloud from lectern and pulpit</li></ul><p>A treasured gift for <strong>parents, grandparents and retiring elders</strong> — and a worthy lectern Bible for the church. Chosen with reverence, delivered with care — from Nairobi across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '👓', 'text' => 'Giant print makes every word prominent — kind to seniors and low-vision readers'], ['icon' => '📖', 'text' => 'NKJV — clear modern English that preserves the King James style'], ['icon' => '🎙️', 'text' => 'Reads beautifully aloud — ideal for lectern and pulpit'], ['icon' => '⛪', 'text' => 'A natural bridge for congregations raised on the King James'], ['icon' => '🎁', 'text' => 'The classic gift for parents, grandparents and retiring elders']], 'aliases' => ['large print bible', 'giant print bible kenya', 'nkjv bible nairobi', 'bible for grandmother', 'bible for seniors', 'big print bible', 'new king james bible kenya', 'lectern bible', 'bible for wazee'], 'seo' => ['meta_title' => 'NKJV Giant Print Bible in Nairobi, Kenya', 'meta_description' => 'Giant print NKJV — the King James\' majesty in clear modern English, easy on every eye. For seniors and pulpits. Delivered across Kenya and worldwide.', 'meta_keywords' => 'nkjv giant print bible, large print bible kenya, giant print bible nairobi, bible for seniors, bible for grandmother, new king james version kenya, lectern bible, nkjv bible nairobi', 'og_title' => 'NKJV Giant Print — Majesty You Can Read', 'og_description' => 'The King James you grew up hearing, in the English you speak — set in giant print that is kind to every eye. Delivered from Nairobi across Kenya and worldwide.']],
        'YX9PKFQQ5' => ['short' => 'Bevelled-glass communion cups, 1½ inches tall for an easy lift from the tray — durable, dishwasher safe and reusable.', 'description' => '<p>Reusable communion cups in bevelled glass, 1½ inches tall. The taller profile is a deliberate kindness: it rises just enough from the communion tray for fingers to grasp it easily as the elements are passed along the pew.</p><p>Glass brings a dignity that disposables cannot — a clear, clean cup with a refined bevelled lip, durable enough to wash and reuse for years of services. These cups are dishwasher safe, so preparing for the Lord\'s Supper and clearing away afterwards is simple work for the serving team.</p><ul><li><strong>Bevelled glass</strong> with a refined lip — 1½ inches (H)</li><li>Taller size for easy grasping out of the communion tray</li><li>Durable and dishwasher safe — reusable service after service</li><li>Perfect for use in church, from small fellowships to great congregations</li></ul><p>From Sonalux House, Moi Avenue, Nairobi — delivered to churches across Kenya, East Africa and worldwide.</p>', 'features' => [['icon' => '🥂', 'text' => 'Bevelled glass with a refined lip — clear, clean dignity for the Lord\'s Supper'], ['icon' => '📏', 'text' => '1½ inches tall — the taller profile lifts easily out of the communion tray'], ['icon' => '💪', 'text' => 'Durable and dishwasher safe — simple work for the serving team'], ['icon' => '♻️', 'text' => 'Reusable for years of services — a lasting alternative to disposables'], ['icon' => '⛪', 'text' => 'Perfect for use in church, from small fellowships to great congregations'], ['icon' => '🚚', 'text' => 'From Moi Avenue, Nairobi — delivery across Kenya, East Africa and worldwide']], 'aliases' => ['communion glasses', 'glass communion cups', 'reusable communion cups', 'beveled communion cups', 'bevelled communion glasses', 'communion cups nairobi', 'vikombe vya ushirika', 'lords supper cups'], 'seo' => ['meta_title' => 'Glass Communion Cups in Nairobi, Kenya', 'meta_description' => 'Durable bevelled-glass communion cups, 1½ in tall, dishwasher safe and easy to lift from the tray. Delivered from Nairobi across Kenya and worldwide.', 'meta_keywords' => 'glass communion cups, communion glasses kenya, reusable communion cups nairobi, beveled communion cups, communion cups for trays, holy communion ware kenya, communion glasses nairobi', 'og_title' => 'Glass Communion Cups — Bevelled, Reusable, Easy from the Tray', 'og_description' => 'Bevelled-glass cups, 1½ inches tall, that lift easily from the communion tray — durable, dishwasher safe and dignified for the Lord\'s Supper. From Bethany House, Nairobi, delivered worldwide.']],
        'YX9PKFQQ5-FDB7-SHIRT' => ['short' => 'Smart straight-collar clergy shirt for pastors and reverends — dependable everyday ministry wear, tailored in Nairobi.', 'description' => '<p>The <strong>Straight Collar Shirt</strong> is the quiet workhorse of the clergy wardrobe: a smart shirt with a straight collar, made for pastors and reverends who want dignified, comfortable dress for everyday ministry.</p><p>Each shirt is made to order in our Nairobi workshop at Sonalux House, Moi Avenue, and cut to your fit. Wear it with a cassock or suit through the week, for services and for every occasion where smart clergy dress is called for.</p><p>Dependable clergy wear for ministers across Kenya and East Africa — Anglican/ACK, Methodist, PCEA, Pentecostal and independent churches — with delivery worldwide.</p>', 'features' => [['icon' => '👔', 'text' => 'Smart straight collar for a clean, dignified ministerial look'], ['icon' => '✂️', 'text' => 'Made to order in our Nairobi workshop, cut to your fit'], ['icon' => '🙏', 'text' => 'Everyday ministry wear for pastors and reverends'], ['icon' => '🧥', 'text' => 'Pairs cleanly with a cassock or suit'], ['icon' => '🌍', 'text' => 'Delivery across Kenya, East Africa and worldwide']], 'aliases' => ['clergy shirts kenya', 'straight collar clergy shirt', 'pastors shirt nairobi', 'reverend shirt kenya', 'clergy wear nairobi', 'minister shirts kenya', 'clergy apparel kenya', 'clergy shirts in kenya'], 'seo' => ['meta_title' => 'Straight Collar Clergy Shirts — Nairobi, Kenya', 'meta_description' => 'Smart straight-collar clergy shirts for pastors and reverends, made to order in Nairobi. Delivery across Kenya, East Africa and worldwide.', 'meta_keywords' => 'straight collar shirt kenya, clergy shirts nairobi, pastors shirt kenya, reverend shirts, clergy wear kenya, minister shirt nairobi, clergy apparel kenya', 'og_title' => 'Straight Collar Shirt — Everyday Clergy Wear', 'og_description' => 'The workhorse of the clergy wardrobe: a smart straight-collar shirt made to order in Nairobi, delivered across Kenya, East Africa and worldwide.']],
